window.KB_QUESTIONS = [{"id":"cnk_j001_q1","tid":"cnk_j001","ty":"choice","df":"basic","p":"化学主要在哪个层次上研究物质？","ch":[{"key":"A","text":"只研究肉眼能看见的大块物体"},{"key":"B","text":"只研究天体的运行"},{"key":"C","text":"分子、原子"},{"key":"D","text":"只研究生物的分类"}],"a":"C","ex":"化学在分子、原子层次上研究物质的组成、结构、性质和变化。"},{"id":"cnk_j001_q2","tid":"cnk_j001","ty":"choice","df":"basic","p":"下列做法能说明化学改善了生活的是？","ch":[{"key":"A","text":"把所有化学制品都看成有害物质"},{"key":"B","text":"拒绝使用任何人造材料"},{"key":"C","text":"认为化学变化一定造成污染"},{"key":"D","text":"用合成药物帮助治疗疾病"}],"a":"D","ex":"化学可以制造药物和材料；化学制品要合理使用，不是一律有害。"},{"id":"cnk_j001_q3","tid":"cnk_j001","ty":"choice","df":"standard","p":"化学研究的内容包括？","ch":[{"key":"A","text":"物质的组成、结构、性质和变化"},{"key":"B","text":"只有物质的颜色和形状"},{"key":"C","text":"只有价格和产量"},{"key":"D","text":"只有生物的遗传"}],"a":"A","ex":"组成、结构、性质和变化都是化学要研究的。"},{"id":"cnk_j001_q4","tid":"cnk_j001","ty":"choice","df":"challenge","p":"学习化学时，较合适的态度是？","ch":[{"key":"A","text":"凭外观断定一种物质有没有用"},{"key":"B","text":"用实验和事实认识物质及其变化"},{"key":"C","text":"把没见过的变化都当成危险而拒绝了解"},{"key":"D","text":"只背名称、不做实验"}],"a":"B","ex":"化学结论要有事实和实验依据，并注意安全和用途。"},{"id":"cnk_j002_q1","tid":"cnk_j002","ty":"choice","df":"basic","p":"有新物质生成的变化是？","ch":[{"key":"A","text":"物理变化"},{"key":"B","text":"只有状态变化"},{"key":"C","text":"只有形状变化"},{"key":"D","text":"化学变化"}],"a":"D","ex":"化学变化的特征是生成新物质；状态、形状改变不一定有新物质。"},{"id":"cnk_j002_q2","tid":"cnk_j002","ty":"choice","df":"basic","p":"下列属于物理变化的是？","ch":[{"key":"A","text":"冰融化成水"},{"key":"B","text":"木炭燃烧"},{"key":"C","text":"铁钉生锈"},{"key":"D","text":"食物腐烂"}],"a":"A","ex":"冰和水是同一种物质；燃烧、生锈和腐烂都生成了新物质。"},{"id":"cnk_j002_q3","tid":"cnk_j002","ty":"choice","df":"standard","p":"不需要发生化学变化就能表现出来的性质是？","ch":[{"key":"A","text":"可燃性"},{"key":"B","text":"颜色、状态和密度"},{"key":"C","text":"能否与酸反应"},{"key":"D","text":"是否容易生锈"}],"a":"B","ex":"颜色、状态、密度属于物理性质；可燃性、与酸反应和生锈属于化学性质。"},{"id":"cnk_j002_q4","tid":"cnk_j002","ty":"choice","df":"challenge","p":"蜡烛燃烧时，蜡油流下后又凝固。其中属于化学变化的是？","ch":[{"key":"A","text":"蜡油受热熔化"},{"key":"B","text":"蜡油冷却凝固"},{"key":"C","text":"石蜡燃烧生成二氧化碳和水"},{"key":"D","text":"把蜡烛掰成两段"}],"a":"C","ex":"燃烧生成了新物质；熔化、凝固和掰断没有生成新物质。"},{"id":"cnk_j003_q1","tid":"cnk_j003","ty":"choice","df":"basic","p":"科学探究中，实验之前通常要先做的是？","ch":[{"key":"A","text":"提出问题并作出猜想"},{"key":"B","text":"直接把结论写好"},{"key":"C","text":"只观察一次就结束"},{"key":"D","text":"不记录现象"}],"a":"A","ex":"探究从问题和猜想开始，再用实验收集证据。"},{"id":"cnk_j003_q2","tid":"cnk_j003","ty":"choice","df":"basic","p":"记录实验现象时，应当？","ch":[{"key":"A","text":"把希望出现的现象写成已经发生"},{"key":"B","text":"写下实际看到的现象"},{"key":"C","text":"只写和猜想一致的内容"},{"key":"D","text":"用结论代替现象"}],"a":"B","ex":"记录的是观察到的现象，结论要在证据之后再写。"},{"id":"cnk_j003_q3","tid":"cnk_j003","ty":"choice","df":"standard","p":"比较两种金属谁更容易与酸反应，较合理的做法是？","ch":[{"key":"A","text":"同时改变金属、酸的浓度和温度"},{"key":"B","text":"不设对照，只试一种金属"},{"key":"C","text":"酸的种类、浓度和温度相同，只改变金属"},{"key":"D","text":"先写下谁更活泼，再挑能符合的现象"}],"a":"C","ex":"比较时要控制其他条件，只改变要研究的因素。"},{"id":"cnk_j003_q4","tid":"cnk_j003","ty":"choice","df":"challenge","p":"实验现象与原来的猜想不一致时，应当？","ch":[{"key":"A","text":"改掉现象，使它符合猜想"},{"key":"B","text":"把这次实验从记录里删掉"},{"key":"C","text":"不再做同类实验"},{"key":"D","text":"根据现象重新分析，必要时再做实验"}],"a":"D","ex":"证据和猜想冲突时，要复查实验并修正猜想，不能改现象。"},{"id":"cnk_j004_q1","tid":"cnk_j004","ty":"choice","df":"basic","p":"闻气体气味时，正确的方法是？","ch":[{"key":"A","text":"把鼻孔凑到瓶口猛吸"},{"key":"B","text":"用手在瓶口轻轻扇动，使少量气体飘进鼻孔"},{"key":"C","text":"用嘴尝一点"},{"key":"D","text":"直接对着瓶口吹气"}],"a":"B","ex":"扇闻可以减少吸入量。实验室里的药品不能品尝。"},{"id":"cnk_j004_q2","tid":"cnk_j004","ty":"choice","df":"basic","p":"给试管里的液体加热，试管口应？","ch":[{"key":"A","text":"对着自己方便观察"},{"key":"B","text":"用拇指堵住"},{"key":"C","text":"不要对着自己或别人"},{"key":"D","text":"竖直向上并加满液体"}],"a":"C","ex":"加热时液体可能喷出，试管口不能对着人；液体一般不超过试管容积的三分之一。"},{"id":"cnk_j004_q3","tid":"cnk_j004","ty":"choice","df":"standard","p":"稀释浓硫酸时，正确的操作是？","ch":[{"key":"A","text":"把水倒进浓硫酸里"},{"key":"B","text":"把浓硫酸一次全部倒入水中后盖紧摇晃"},{"key":"C","text":"在量筒里稀释"},{"key":"D","text":"把浓硫酸沿器壁慢慢注入水中，并用玻璃棒搅拌"}],"a":"D","ex":"稀释时把浓硫酸慢慢加入水中，并不断搅拌。水倒进浓硫酸会因放热而飞溅。"},{"id":"cnk_j004_q4","tid":"cnk_j004","ty":"choice","df":"challenge","p":"过滤时，玻璃棒的作用是？","ch":[{"key":"A","text":"引流，使液体沿玻璃棒流入漏斗"},{"key":"B","text":"搅拌滤纸，让过滤更快"},{"key":"C","text":"捣破滤纸上的不溶物"},{"key":"D","text":"代替滤纸挡住杂质"}],"a":"A","ex":"玻璃棒下端靠在三层滤纸一侧，用来引流。滤纸不能戳破。"},{"id":"cnk_j005_q1","tid":"cnk_j005","ty":"choice","df":"basic","p":"空气中体积分数最大的气体是？","ch":[{"key":"A","text":"氧气"},{"key":"B","text":"二氧化碳"},{"key":"C","text":"氮气"},{"key":"D","text":"氢气"}],"a":"C","ex":"氮气约占空气体积的 78%，氧气约占 21%。"},{"id":"cnk_j005_q2","tid":"cnk_j005","ty":"choice","df":"basic","p":"测定空气里氧气含量时，红磷燃烧后打开弹簧夹，水进入集气瓶约五分之一。由此说明？","ch":[{"key":"A","text":"氮气约占五分之一"},{"key":"B","text":"空气全部是氧气"},{"key":"C","text":"剩余气体也能支持燃烧"},{"key":"D","text":"氧气约占空气体积的五分之一"}],"a":"D","ex":"红磷只消耗氧气，进入的水约占瓶内空气体积的五分之一。"},{"id":"cnk_j005_q3","tid":"cnk_j005","ty":"choice","df":"standard","p":"下列关于空气的说法，正确的是？","ch":[{"key":"A","text":"空气是混合物"},{"key":"B","text":"空气是一种单质"},{"key":"C","text":"空气是只由氧气组成的纯净物"},{"key":"D","text":"空气中没有氮气"}],"a":"A","ex":"空气含有氮气、氧气、稀有气体和二氧化碳等，属于混合物。"},{"id":"cnk_j005_q4","tid":"cnk_j005","ty":"numeric","df":"challenge","p":"空气中氧气约占体积的 21%。100 L 这样的空气里，氧气约有多少升？","a":"21","ex":"100 乘 21% 等于 21 L。氮气约占 78 L，不是氧气。"},{"id":"cnk_j006_q1","tid":"cnk_j006","ty":"choice","df":"basic","p":"检验一瓶气体是不是氧气，常用的方法是？","ch":[{"key":"A","text":"看气体是不是无色"},{"key":"B","text":"闻气味是否刺鼻"},{"key":"C","text":"倒入澄清石灰水看是否变浑浊"},{"key":"D","text":"把带火星的木条伸入瓶中，木条复燃"}],"a":"D","ex":"氧气能使带火星的木条复燃。无色不能区分空气和氧气。"},{"id":"cnk_j006_q2","tid":"cnk_j006","ty":"choice","df":"basic","p":"氧气的物理性质是？","ch":[{"key":"A","text":"通常为无色、无味气体，密度比空气略大，不易溶于水"},{"key":"B","text":"有刺激性气味"},{"key":"C","text":"密度比空气小得多"},{"key":"D","text":"极易溶于水"}],"a":"A","ex":"氧气无色无味，密度比空气略大，在水中溶解得不多，所以常用排水法收集。"},{"id":"cnk_j006_q3","tid":"cnk_j006","ty":"choice","df":"standard","p":"铁丝在氧气中燃烧的主要现象是？","ch":[{"key":"A","text":"安静燃烧，发出淡蓝色火焰，生成水"},{"key":"B","text":"剧烈燃烧，火星四射，生成黑色固体"},{"key":"C","text":"产生大量白雾"},{"key":"D","text":"火焰呈蓝色，生成有刺激性气味的气体"}],"a":"B","ex":"铁在氧气中燃烧生成四氧化三铁，是黑色固体。硫燃烧才是蓝色火焰和刺激性气味。"},{"id":"cnk_j006_q4","tid":"cnk_j006","ty":"choice","df":"challenge","p":"下列说法正确的是？","ch":[{"key":"A","text":"氧气没有气味，所以不能支持燃烧"},{"key":"B","text":"氧气只在加热时才是气体"},{"key":"C","text":"氧气能支持燃烧，一般本身不燃烧"},{"key":"D","text":"任何物质在氧气中都不反应"}],"a":"C","ex":"氧气是助燃气体。可燃物在氧气中燃烧，氧气本身通常不作为燃料燃烧。"},{"id":"cnk_j007_q1","tid":"cnk_j007","ty":"choice","df":"basic","p":"实验室用过氧化氢溶液和二氧化锰制氧气，二氧化锰的作用是？","ch":[{"key":"A","text":"催化剂，能加快反应，反应前后质量和化学性质不变"},{"key":"B","text":"提供氧气的反应物，会全部消耗"},{"key":"C","text":"只用来干燥氧气"},{"key":"D","text":"使氧气变成液体"}],"a":"A","ex":"二氧化锰是催化剂，能改变化学反应速率，本身的质量和化学性质在反应前后不变。"},{"id":"cnk_j007_q2","tid":"cnk_j007","ty":"choice","df":"basic","p":"用高锰酸钾制氧气，发生装置应选用？","ch":[{"key":"A","text":"固体与液体在常温下混合、不加热"},{"key":"B","text":"固体加热型"},{"key":"C","text":"只要长颈漏斗、不能加热"},{"key":"D","text":"只要水槽、不要试管"}],"a":"B","ex":"高锰酸钾是固体，需要加热。过氧化氢和二氧化锰在常温下就能反应。"},{"id":"cnk_j007_q3","tid":"cnk_j007","ty":"choice","df":"standard","p":"氧气可以用排水法收集，主要因为？","ch":[{"key":"A","text":"氧气极易溶于水"},{"key":"B","text":"氧气密度比空气小得多，只能用向下排空气法"},{"key":"C","text":"氧气不易溶于水，且密度比空气略大时也可用向上排空气法"},{"key":"D","text":"氧气能在水中燃烧"}],"a":"C","ex":"氧气不易溶于水，适合排水法；密度比空气略大，也可用向上排空气法。"},{"id":"cnk_j007_q4","tid":"cnk_j007","ty":"choice","df":"challenge","p":"下列反应属于分解反应的是？","ch":[{"key":"A","text":"碳在氧气中燃烧生成二氧化碳"},{"key":"B","text":"铁丝在氧气中燃烧生成四氧化三铁"},{"key":"C","text":"红磷在空气中燃烧"},{"key":"D","text":"过氧化氢在二氧化锰催化下生成水和氧气"}],"a":"D","ex":"一种物质生成两种或更多物质，是分解反应。后三个都是物质与氧气化合。"},{"id":"cnk_j008_q1","tid":"cnk_j008","ty":"choice","df":"basic","p":"制取氧气前，必须先做的一步是？","ch":[{"key":"A","text":"先把导管口堵死再加热"},{"key":"B","text":"检查装置气密性"},{"key":"C","text":"收集满后再检查"},{"key":"D","text":"直接闻瓶内气体"}],"a":"B","ex":"装置漏气就收集不到氧气，所以要先检查气密性。"},{"id":"cnk_j008_q2","tid":"cnk_j008","ty":"choice","df":"basic","p":"用排水法收集氧气，导管口开始冒出的气泡应？","ch":[{"key":"A","text":"一有气泡就立刻收集"},{"key":"B","text":"把开始的气泡全部收进瓶里当纯氧气"},{"key":"C","text":"等气泡连续、均匀后再收集"},{"key":"D","text":"等到没有气泡再收集"}],"a":"C","ex":"开始排出的是装置里的空气，连续均匀的气泡才主要是氧气。"},{"id":"cnk_j008_q3","tid":"cnk_j008","ty":"choice","df":"standard","p":"收集到的氧气，检验时木条应？","ch":[{"key":"A","text":"燃着后放在瓶口外面不动"},{"key":"B","text":"浸入过氧化氢溶液"},{"key":"C","text":"先蘸水再伸入"},{"key":"D","text":"带火星伸入集气瓶"}],"a":"D","ex":"带火星的木条伸入氧气中会复燃。瓶口外空气多，现象不明显。"},{"id":"cnk_j008_q4","tid":"cnk_j008","ty":"choice","df":"challenge","p":"实验结束后，二氧化锰应当？","ch":[{"key":"A","text":"回收，它的质量和化学性质基本不变"},{"key":"B","text":"倒进下水道"},{"key":"C","text":"当成已经耗尽的氧气扔掉"},{"key":"D","text":"放回原装过氧化氢瓶"}],"a":"A","ex":"催化剂反应前后质量和化学性质不变，应回收，不要与试剂混放。"},{"id":"cnk_j009_q1","tid":"cnk_j009","ty":"choice","df":"basic","p":"墙内开花墙外香，主要说明？","ch":[{"key":"A","text":"分子之间没有间隔"},{"key":"B","text":"分子在化学变化中不分裂"},{"key":"C","text":"分子在不断运动"},{"key":"D","text":"墙能挡住所有分子"}],"a":"C","ex":"花的香味分子运动到墙外，说明分子在不断运动。"},{"id":"cnk_j009_q2","tid":"cnk_j009","ty":"choice","df":"basic","p":"酒精和水混合后总体积小于两者体积之和，主要因为？","ch":[{"key":"A","text":"酒精分子变成了水分子"},{"key":"B","text":"混合时分子停止运动"},{"key":"C","text":"两种液体发生了燃烧"},{"key":"D","text":"分子之间有间隔"}],"a":"D","ex":"分子间有间隔，混合时一种分子可以进入另一种分子的间隔。"},{"id":"cnk_j009_q3","tid":"cnk_j009","ty":"choice","df":"standard","p":"化学变化中，下列说法正确的是？","ch":[{"key":"A","text":"分子可以分成原子，原子再组合成新的分子"},{"key":"B","text":"原子分成更小的质子后种类就变了"},{"key":"C","text":"分子永远不能再分"},{"key":"D","text":"原子的种类一定会改变"}],"a":"A","ex":"化学变化中分子分裂成原子，原子重新组合。原子的种类不变。"},{"id":"cnk_j009_q4","tid":"cnk_j009","ty":"choice","df":"challenge","p":"水结成冰，水分子本身？","ch":[{"key":"A","text":"分成了氢原子和氧原子"},{"key":"B","text":"没有变成其他分子"},{"key":"C","text":"变成了氧气分子"},{"key":"D","text":"数目一定减半"}],"a":"B","ex":"结冰是物理变化，水分子本身不变，只是间隔和排列方式改变。"},{"id":"cnk_j010_q1","tid":"cnk_j010","ty":"choice","df":"basic","p":"原子的中心部分是？","ch":[{"key":"A","text":"核外电子"},{"key":"B","text":"分子"},{"key":"C","text":"元素符号"},{"key":"D","text":"原子核"}],"a":"D","ex":"原子核位于原子中心，电子在核外运动。"},{"id":"cnk_j010_q2","tid":"cnk_j010","ty":"choice","df":"basic","p":"原子核所带的电是？","ch":[{"key":"A","text":"正电"},{"key":"B","text":"负电"},{"key":"C","text":"不带电，因为里面只有电子"},{"key":"D","text":"与电子相同的负电"}],"a":"A","ex":"质子带正电，中子不带电，所以原子核带正电；电子带负电。"},{"id":"cnk_j010_q3","tid":"cnk_j010","ty":"choice","df":"standard","p":"在原子中，质子数与核外电子数的关系是？","ch":[{"key":"A","text":"质子数一定大于电子数"},{"key":"B","text":"相等，整个原子不显电性"},{"key":"C","text":"电子数一定是质子数的两倍"},{"key":"D","text":"没有关系"}],"a":"B","ex":"质子带的正电与电子带的负电数量相等，原子整体不带电。"},{"id":"cnk_j010_q4","tid":"cnk_j010","ty":"choice","df":"challenge","p":"相对原子质量主要取决于？","ch":[{"key":"A","text":"核外电子数"},{"key":"B","text":"元素符号的字母个数"},{"key":"C","text":"质子数与中子数之和"},{"key":"D","text":"原子的体积一定等于质量"}],"a":"C","ex":"质子和中子的质量远大于电子，相对原子质量主要由质子数和中子数决定。"},{"id":"cnk_j011_q1","tid":"cnk_j011","ty":"choice","df":"basic","p":"决定元素种类的是？","ch":[{"key":"A","text":"质子数（核电荷数）"},{"key":"B","text":"中子数"},{"key":"C","text":"核外电子层数一定相同才算同一种元素"},{"key":"D","text":"相对原子质量的小数部分"}],"a":"A","ex":"质子数相同的一类原子属于同一种元素。中子数不同可以是同种元素的不同原子。"},{"id":"cnk_j011_q2","tid":"cnk_j011","ty":"choice","df":"basic","p":"书写元素符号时，正确的是？","ch":[{"key":"A","text":"全部大写"},{"key":"B","text":"第一个字母大写，若有第二个字母则小写"},{"key":"C","text":"全部小写"},{"key":"D","text":"第二个字母大写、第一个小写"}],"a":"B","ex":"例如 Cu、Fe、Na，第一个字母大写，第二个字母小写。"},{"id":"cnk_j011_q3","tid":"cnk_j011","ty":"choice","df":"standard","p":"下列符号表示一种元素，而不是一种物质化学式的是？","ch":[{"key":"A","text":"O2"},{"key":"B","text":"H2O"},{"key":"C","text":"Cu"},{"key":"D","text":"CO2"}],"a":"C","ex":"Cu 是铜元素的符号，也可表示铜单质。O2、H2O、CO2 是化学式，标出了原子个数。"},{"id":"cnk_j011_q4","tid":"cnk_j011","ty":"choice","df":"challenge","p":"在元素周期表的一格中，通常能直接看到？","ch":[{"key":"A","text":"该元素的价格"},{"key":"B","text":"实验室制法"},{"key":"C","text":"是否有毒的完整说明"},{"key":"D","text":"原子序数、元素符号和相对原子质量"}],"a":"D","ex":"周期表的每一格给出原子序数、元素符号、名称和相对原子质量。原子序数等于质子数。"},{"id":"cnk_j012_q1","tid":"cnk_j012","ty":"choice","df":"basic","p":"净化水时，能把不溶性杂质与液体分离的操作是？","ch":[{"key":"A","text":"吸附色素"},{"key":"B","text":"过滤"},{"key":"C","text":"蒸馏得到蒸馏水"},{"key":"D","text":"通电分解"}],"a":"B","ex":"过滤除去的是不溶性杂质。活性炭吸附色素和异味，蒸馏得到的水更纯净。"},{"id":"cnk_j012_q2","tid":"cnk_j012","ty":"choice","df":"basic","p":"活性炭在净水中的主要作用是？","ch":[{"key":"A","text":"把海水全部变成蒸馏水"},{"key":"B","text":"使水发生分解反应"},{"key":"C","text":"吸附色素和异味"},{"key":"D","text":"增加水中的泥沙"}],"a":"C","ex":"活性炭有吸附性，能去掉一些色素和异味，不能把所有可溶杂质都变成沉淀。"},{"id":"cnk_j012_q3","tid":"cnk_j012","ty":"choice","df":"standard","p":"下列做法有利于保护水资源的是？","ch":[{"key":"A","text":"用完的电池扔进池塘"},{"key":"B","text":"工业废水不经处理直接排放"},{"key":"C","text":"觉得水取之不尽而长流水"},{"key":"D","text":"用完水后拧紧水龙头，不把废液倒进河中"}],"a":"D","ex":"节约用水、不随意排放废水，才能保护有限的淡水。"},{"id":"cnk_j012_q4","tid":"cnk_j012","ty":"choice","df":"challenge","p":"要得到较纯净的蒸馏水，应采用？","ch":[{"key":"A","text":"蒸馏"},{"key":"B","text":"只静置沉淀"},{"key":"C","text":"只过滤一次"},{"key":"D","text":"加入活性炭后不再处理"}],"a":"A","ex":"蒸馏把水蒸发再冷凝，得到的水比较纯净。沉淀和过滤主要去掉不溶性杂质。"},{"id":"cnk_j013_q1","tid":"cnk_j013","ty":"choice","df":"basic","p":"电解水的实验说明水是？","ch":[{"key":"A","text":"一种单质"},{"key":"B","text":"氢气和氧气的混合物"},{"key":"C","text":"由氢元素和氧元素组成的化合物"},{"key":"D","text":"只含氧元素"}],"a":"C","ex":"水通电生成氢气和氧气，说明水由氢、氧两种元素组成，是化合物。"},{"id":"cnk_j013_q2","tid":"cnk_j013","ty":"choice","df":"basic","p":"电解水时，与电源负极相连的一端得到的气体是？","ch":[{"key":"A","text":"氧气"},{"key":"B","text":"空气"},{"key":"C","text":"二氧化碳"},{"key":"D","text":"氢气"}],"a":"D","ex":"负极产生氢气，正极产生氧气。氢气体积大约是氧气的 2 倍。"},{"id":"cnk_j013_q3","tid":"cnk_j013","ty":"choice","df":"standard","p":"检验电解水得到的氢气，可用的现象是？","ch":[{"key":"A","text":"用燃着的木条点燃，气体燃烧，产生淡蓝色火焰"},{"key":"B","text":"带火星的木条复燃"},{"key":"C","text":"使澄清石灰水变浑浊"},{"key":"D","text":"使干燥的红色石蕊试纸变蓝"}],"a":"A","ex":"氢气可燃，火焰呈淡蓝色。复燃是氧气，石灰水变浑浊是二氧化碳。"},{"id":"cnk_j013_q4","tid":"cnk_j013","ty":"numeric","df":"challenge","p":"电解水得到氧气 16 mL。按体积比，同时得到的氢气约是多少毫升？","a":"32","ex":"氢气与氧气的体积比约为 2:1，所以氢气约 32 mL。"},{"id":"cnk_j014_q1","tid":"cnk_j014","ty":"choice","df":"basic","p":"化学式 H2O 表示？","ch":[{"key":"A","text":"水是由 2 个氢分子和 1 个氧分子混合而成"},{"key":"B","text":"水中只有氢元素"},{"key":"C","text":"水是单质"},{"key":"D","text":"1 个水分子由 2 个氢原子和 1 个氧原子构成"}],"a":"D","ex":"元素符号右下角的数字是一个分子中该原子的个数。"},{"id":"cnk_j014_q2","tid":"cnk_j014","ty":"choice","df":"basic","p":"在化合物中，正负化合价的代数和？","ch":[{"key":"A","text":"等于 0"},{"key":"B","text":"一定等于 +1"},{"key":"C","text":"一定等于该元素的质子数"},{"key":"D","text":"可以随便写"}],"a":"A","ex":"化合物里正价总数与负价总数相等，代数和为 0。"},{"id":"cnk_j014_q3","tid":"cnk_j014","ty":"choice","df":"standard","p":"已知氧通常为 -2 价、钙为 +2 价，氧化钙的化学式是？","ch":[{"key":"A","text":"CaO2"},{"key":"B","text":"CaO"},{"key":"C","text":"Ca2O"},{"key":"D","text":"OCa2"}],"a":"B","ex":"钙 +2、氧 -2，代数和为 0，化学式写作 CaO。"},{"id":"cnk_j014_q4","tid":"cnk_j014","ty":"choice","df":"challenge","p":"元素符号与化学式的区别，正确的一组是？","ch":[{"key":"A","text":"O2 只表示一个氧原子"},{"key":"B","text":"H 表示氢气分子"},{"key":"C","text":"O 表示氧元素，O2 表示氧气"},{"key":"D","text":"CO2 中的 2 表示 2 个二氧化碳分子"}],"a":"C","ex":"O 是元素符号；O2 是氧气的化学式，表示一个氧分子由两个氧原子构成。"},{"id":"cnk_j015_q1","tid":"cnk_j015","ty":"choice","df":"basic","p":"相对分子质量等于？","ch":[{"key":"A","text":"化学式中各原子的相对原子质量之和"},{"key":"B","text":"化学式中各元素符号的字母个数"},{"key":"C","text":"只取其中最大的相对原子质量"},{"key":"D","text":"质子数与电子数之差"}],"a":"A","ex":"把每个原子的相对原子质量相加，同种原子要乘个数。"},{"id":"cnk_j015_q2","tid":"cnk_j015","ty":"choice","df":"basic","p":"水的化学式是 H2O。其中氢原子与氧原子的个数比是？","ch":[{"key":"A","text":"1:2"},{"key":"B","text":"2:1"},{"key":"C","text":"1:1"},{"key":"D","text":"2:16"}],"a":"B","ex":"右下角数字表示原子个数，氢有 2 个，氧有 1 个。"},{"id":"cnk_j015_q3","tid":"cnk_j015","ty":"numeric","df":"standard","p":"已知氢的相对原子质量为 1，氧为 16。水的相对分子质量是多少？","a":"18","ex":"1 乘 2 再加 16，等于 18。"},{"id":"cnk_j015_q4","tid":"cnk_j015","ty":"numeric","df":"challenge","p":"已知氢的相对原子质量为 1，氧为 16。36 g 水中，氢元素的质量是多少克？","a":"4","ex":"水中氢元素的质量占 2/18。36 乘 2 再除以 18，等于 4 g。"},{"id":"cnk_j016_q1","tid":"cnk_j016","ty":"choice","df":"basic","p":"电解水实验中，体积较小的那一端气体能使？","ch":[{"key":"A","text":"燃着的木条燃烧更旺并本身被点燃成淡蓝色火焰后消失在石灰水里"},{"key":"B","text":"带火星的木条复燃"},{"key":"C","text":"澄清石灰水一定变浑浊"},{"key":"D","text":"紫色石蕊变红"}],"a":"B","ex":"体积较小的是氧气，能使带火星的木条复燃。体积较大的是氢气。"},{"id":"cnk_j016_q2","tid":"cnk_j016","ty":"choice","df":"basic","p":"做电解水实验时，为了增强水的导电性，可以？","ch":[{"key":"A","text":"加入大量食盐并品尝溶液"},{"key":"B","text":"把电极直接握在手里"},{"key":"C","text":"在水中加入少量氢氧化钠或稀硫酸"},{"key":"D","text":"改用纯油代替水"}],"a":"C","ex":"纯水导电能力很弱。少量氢氧化钠或稀硫酸能增强导电性。溶液不能品尝。"},{"id":"cnk_j016_q3","tid":"cnk_j016","ty":"choice","df":"standard","p":"若正极得到氧气 5 mL，负极得到的氢气接近？","ch":[{"key":"A","text":"5 mL"},{"key":"B","text":"2.5 mL"},{"key":"C","text":"15 mL"},{"key":"D","text":"10 mL"}],"a":"D","ex":"氢气体积约是氧气的 2 倍。"},{"id":"cnk_j016_q4","tid":"cnk_j016","ty":"choice","df":"challenge","p":"电解水生成氢气和氧气，这一变化属于？","ch":[{"key":"A","text":"化学变化"},{"key":"B","text":"只有物理变化，因为水还在"},{"key":"C","text":"过滤"},{"key":"D","text":"蒸馏"}],"a":"A","ex":"生成了新物质氢气和氧气，是化学变化。"},{"id":"cnk_j017_q1","tid":"cnk_j017","ty":"choice","df":"basic","p":"质量守恒定律说的是？","ch":[{"key":"A","text":"反应前后分子个数一定相等"},{"key":"B","text":"反应前后体积一定相等"},{"key":"C","text":"参加反应的各物质质量总和等于生成的各物质质量总和"},{"key":"D","text":"所有物质的质量在任何时候都不变，包括没有参加反应的"}],"a":"C","ex":"只计算实际参加反应的物质和生成的物质，两边质量相等。"},{"id":"cnk_j017_q2","tid":"cnk_j017","ty":"choice","df":"basic","p":"从微观上看，化学变化前后不变的是？","ch":[{"key":"A","text":"分子的种类"},{"key":"B","text":"物质的种类"},{"key":"C","text":"元素的化合价一定不变"},{"key":"D","text":"原子的种类、数目和质量"}],"a":"D","ex":"原子重新组合，种类、数目和质量不变，所以总质量不变。分子种类会变。"},{"id":"cnk_j017_q3","tid":"cnk_j017","ty":"choice","df":"standard","p":"镁条在密闭容器中燃烧，反应后容器内物质的总质量？","ch":[{"key":"A","text":"不变"},{"key":"B","text":"一定变小，因为生成了气体"},{"key":"C","text":"一定变大，因为结合了容器外的空气"},{"key":"D","text":"变为 0"}],"a":"A","ex":"密闭时氧气也在容器内，参加反应的镁和氧气的质量等于生成的氧化镁的质量。"},{"id":"cnk_j017_q4","tid":"cnk_j017","ty":"numeric","df":"challenge","p":"12 g 碳与 32 g 氧气完全反应，生成二氧化碳的质量是多少克？","a":"44","ex":"参加反应的碳和氧气一共 44 g，生成的二氧化碳也是 44 g。"},{"id":"cnk_j018_q1","tid":"cnk_j018","ty":"choice","df":"basic","p":"书写化学方程式的依据是？","ch":[{"key":"A","text":"只把反应物和生成物的名称连起来"},{"key":"B","text":"为了配平可以改写化学式里的原子个数"},{"key":"C","text":"不需要配平"},{"key":"D","text":"客观事实和质量守恒定律"}],"a":"D","ex":"必须符合事实，并且两边每种原子的个数相等。"},{"id":"cnk_j018_q2","tid":"cnk_j018","ty":"choice","df":"basic","p":"配平化学方程式时，可以改动的是？","ch":[{"key":"A","text":"化学式前面的计量数"},{"key":"B","text":"化学式中原子右下角的数字"},{"key":"C","text":"元素符号里的字母"},{"key":"D","text":"生成物的种类，使它更好配"}],"a":"A","ex":"改右下角的数字就改变了物质。只能改化学式前面的计量数。"},{"id":"cnk_j018_q3","tid":"cnk_j018","ty":"choice","df":"standard","p":"化学方程式 2H2 + O2 =点燃= 2H2O 中，计量数配平后，左边氧原子个数是？","ch":[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"4"},{"key":"D","text":"0"}],"a":"B","ex":"一个氧气分子有 2 个氧原子，计量数是 1，左边氧原子共 2 个，与右边两个水分子中的氧原子相等。"},{"id":"cnk_j018_q4","tid":"cnk_j018","ty":"choice","df":"challenge","p":"化学方程式中，标在箭号上方的「点燃」或「加热」表示？","ch":[{"key":"A","text":"生成物的状态"},{"key":"B","text":"该物质不参加反应"},{"key":"C","text":"反应条件"},{"key":"D","text":"计量数"}],"a":"C","ex":"反应条件写在等号或箭号的上方。气体、沉淀的箭头表示生成物状态。"},{"id":"cnk_j019_q1","tid":"cnk_j019","ty":"choice","df":"basic","p":"根据化学方程式计算时，代入的质量必须是？","ch":[{"key":"A","text":"实际参加反应的纯净物质量"},{"key":"B","text":"混合物的总质量"},{"key":"C","text":"容器的质量"},{"key":"D","text":"溶剂的质量"}],"a":"A","ex":"杂质和没有参加反应的物质不能直接代入化学方程式。"},{"id":"cnk_j019_q2","tid":"cnk_j019","ty":"choice","df":"basic","p":"计算前，化学方程式应当？","ch":[{"key":"A","text":"不配平，直接用化学式右下角的数字"},{"key":"B","text":"先配平，再用各物质的相对分子质量之比"},{"key":"C","text":"只写文字表达式"},{"key":"D","text":"改动化学式使数字更好算"}],"a":"B","ex":"配平后，各物质的质量比等于相对分子质量与计量数乘积之比。"},{"id":"cnk_j019_q3","tid":"cnk_j019","ty":"numeric","df":"standard","p":"已知氢的相对原子质量为 1，氧为 16。电解 36 g 水，理论上生成氧气多少克？","a":"32","ex":"2H2O 通电生成 2H2 和 O2。36 g 水对应的相对质量和是 36，氧气的相对分子质量是 32，所以生成氧气 32 g。"},{"id":"cnk_j019_q4","tid":"cnk_j019","ty":"numeric","df":"challenge","p":"已知钙 40、碳 12、氧 16。高温煅烧 100 g 碳酸钙，化学方程式为 CaCO3 =高温= CaO + CO2。理论上生成二氧化碳多少克？","a":"44","ex":"碳酸钙相对分子质量 100，二氧化碳 44。100 g 碳酸钙完全分解，生成二氧化碳 44 g。"},{"id":"cnk_j020_q1","tid":"cnk_j020","ty":"choice","df":"basic","p":"金刚石和石墨的相同点是？","ch":[{"key":"A","text":"硬度都很大"},{"key":"B","text":"都由碳元素组成"},{"key":"C","text":"都能导电"},{"key":"D","text":"外观都是黑色粉末"}],"a":"B","ex":"二者都是碳单质，但结构不同，硬度和导电性差很多。"},{"id":"cnk_j020_q2","tid":"cnk_j020","ty":"choice","df":"basic","p":"铅笔芯用石墨，主要利用石墨的哪种性质？","ch":[{"key":"A","text":"硬度比金刚石还大"},{"key":"B","text":"在常温下是气体"},{"key":"C","text":"质软、呈深灰色，能在纸上留下痕迹"},{"key":"D","text":"极易溶于水"}],"a":"C","ex":"石墨质软、色深，能留下痕迹。金刚石很硬，不能用来写字。"},{"id":"cnk_j020_q3","tid":"cnk_j020","ty":"choice","df":"standard","p":"活性炭能去除水中的色素和异味，是因为？","ch":[{"key":"A","text":"它把色素都变成了碳单质"},{"key":"B","text":"它使水发生了电解"},{"key":"C","text":"色素都是不溶性大颗粒，被过滤留下"},{"key":"D","text":"它有吸附性"}],"a":"D","ex":"活性炭疏松多孔，能吸附一些色素和气味。"},{"id":"cnk_j020_q4","tid":"cnk_j020","ty":"choice","df":"challenge","p":"下列物质都由碳元素组成的一组是？","ch":[{"key":"A","text":"金刚石、石墨、C60"},{"key":"B","text":"一氧化碳、二氧化碳、碳酸钙"},{"key":"C","text":"氧气、臭氧"},{"key":"D","text":"铁、铜、铝"}],"a":"A","ex":"金刚石、石墨和 C60 都是碳单质。后几组不是同一种元素的单质。"},{"id":"cnk_j021_q1","tid":"cnk_j021","ty":"choice","df":"basic","p":"检验二氧化碳的常用试剂是？","ch":[{"key":"A","text":"带火星的木条"},{"key":"B","text":"紫色石蕊试纸一定变蓝"},{"key":"C","text":"澄清石灰水"},{"key":"D","text":"灼热的铜丝"}],"a":"C","ex":"二氧化碳使澄清石灰水变浑浊，生成碳酸钙白色沉淀。"},{"id":"cnk_j021_q2","tid":"cnk_j021","ty":"choice","df":"basic","p":"二氧化碳的物理性质是？","ch":[{"key":"A","text":"有刺激性气味"},{"key":"B","text":"密度比空气小"},{"key":"C","text":"不溶于水"},{"key":"D","text":"无色、无味气体，密度比空气大，能溶于水"}],"a":"D","ex":"二氧化碳密度比空气大，可用向上排空气法收集；它能溶于水，一般不用排水法。"},{"id":"cnk_j021_q3","tid":"cnk_j021","ty":"choice","df":"standard","p":"把二氧化碳通入滴有紫色石蕊的水中，溶液变红，是因为？","ch":[{"key":"A","text":"二氧化碳与水反应生成碳酸"},{"key":"B","text":"二氧化碳本身是红色气体"},{"key":"C","text":"石蕊把二氧化碳变成了氧气"},{"key":"D","text":"水分解出了盐酸"}],"a":"A","ex":"碳酸使石蕊变红。二氧化碳本身是无色气体。"},{"id":"cnk_j021_q4","tid":"cnk_j021","ty":"choice","df":"challenge","p":"干冰可用于人工降雨，是因为干冰？","ch":[{"key":"A","text":"是固态水，熔化后变成雨"},{"key":"B","text":"是固态二氧化碳，升华时吸收大量热"},{"key":"C","text":"是氧气的固体"},{"key":"D","text":"在空气中燃烧放热"}],"a":"B","ex":"干冰升华吸热，使空气中的水蒸气冷凝。干冰不是冰。"},{"id":"cnk_j022_q1","tid":"cnk_j022","ty":"choice","df":"basic","p":"一氧化碳的一个显著危害是？","ch":[{"key":"A","text":"没有气味所以完全无害"},{"key":"B","text":"不能燃烧"},{"key":"C","text":"密度比空气大得多，会沉在瓶底支持呼吸"},{"key":"D","text":"有毒，能与血液中的血红蛋白结合"}],"a":"D","ex":"一氧化碳无色无味、有毒，容易被人忽视。"},{"id":"cnk_j022_q2","tid":"cnk_j022","ty":"choice","df":"basic","p":"一氧化碳燃烧的生成物是？","ch":[{"key":"A","text":"二氧化碳"},{"key":"B","text":"碳单质和水"},{"key":"C","text":"氢气"},{"key":"D","text":"碳酸钙"}],"a":"A","ex":"一氧化碳在氧气中燃烧生成二氧化碳。"},{"id":"cnk_j022_q3","tid":"cnk_j022","ty":"choice","df":"standard","p":"一氧化碳与氧化铜在加热时反应，生成？","ch":[{"key":"A","text":"只有氧气"},{"key":"B","text":"铜和二氧化碳"},{"key":"C","text":"碳和水"},{"key":"D","text":"氧化铜不变化"}],"a":"B","ex":"一氧化碳能夺走氧化铜中的氧，生成铜和二氧化碳。"},{"id":"cnk_j022_q4","tid":"cnk_j022","ty":"choice","df":"challenge","p":"区分一氧化碳和二氧化碳，可行的是？","ch":[{"key":"A","text":"只看颜色，因为二者颜色不同"},{"key":"B","text":"用鼻子深吸辨别"},{"key":"C","text":"看能否使澄清石灰水变浑浊，或能否被点燃"},{"key":"D","text":"看密度是否都比空气小"}],"a":"C","ex":"二氧化碳使石灰水变浑浊且一般不燃烧；一氧化碳可燃，本身不能使石灰水变浑浊。二者都无色，不能靠闻。"},{"id":"cnk_j023_q1","tid":"cnk_j023","ty":"choice","df":"basic","p":"实验室制取二氧化碳，常用的药品是？","ch":[{"key":"A","text":"大理石（或石灰石）和稀盐酸"},{"key":"B","text":"大理石和稀硫酸"},{"key":"C","text":"石灰石和氯化钠溶液"},{"key":"D","text":"碳和氧气在常温下混合"}],"a":"A","ex":"碳酸钙与稀盐酸反应生成二氧化碳。稀硫酸与碳酸钙反应生成的硫酸钙微溶，会阻碍反应继续。"},{"id":"cnk_j023_q2","tid":"cnk_j023","ty":"choice","df":"basic","p":"制取二氧化碳的发生装置与哪一种制氧气的装置同类？","ch":[{"key":"A","text":"加热高锰酸钾"},{"key":"B","text":"过氧化氢溶液和二氧化锰、不加热"},{"key":"C","text":"加热氯酸钾和二氧化锰"},{"key":"D","text":"电解水"}],"a":"B","ex":"大理石是块状固体，稀盐酸是液体，反应不需要加热。"},{"id":"cnk_j023_q3","tid":"cnk_j023","ty":"choice","df":"standard","p":"收集二氧化碳应选用？","ch":[{"key":"A","text":"排水法，因为二氧化碳难溶于水"},{"key":"B","text":"向下排空气法"},{"key":"C","text":"向上排空气法"},{"key":"D","text":"用带火星的木条在瓶口验满后改用排水法"}],"a":"C","ex":"二氧化碳密度比空气大，能溶于水，所以用向上排空气法，不用排水法。"},{"id":"cnk_j023_q4","tid":"cnk_j023","ty":"choice","df":"challenge","p":"验满二氧化碳时，应将？","ch":[{"key":"A","text":"带火星的木条伸入瓶底，看是否复燃"},{"key":"B","text":"澄清石灰水倒进发生装置"},{"key":"C","text":"用手摸瓶壁是否发热"},{"key":"D","text":"燃着的木条放在集气瓶口，木条熄灭"}],"a":"D","ex":"瓶口处木条熄灭，说明瓶内已集满不支持燃烧的二氧化碳。"},{"id":"cnk_j024_q1","tid":"cnk_j024","ty":"choice","df":"basic","p":"制取二氧化碳时，长颈漏斗的下端应？","ch":[{"key":"A","text":"留在橡皮塞上方"},{"key":"B","text":"伸入液面以下"},{"key":"C","text":"插到试管底部的固体里并露出液面"},{"key":"D","text":"横放在桌面上"}],"a":"B","ex":"下端浸入液面，气体才不会从漏斗跑掉。"},{"id":"cnk_j024_q2","tid":"cnk_j024","ty":"choice","df":"basic","p":"把二氧化碳慢慢倒入放有阶梯蜡烛的烧杯，先熄灭的是？","ch":[{"key":"A","text":"上层蜡烛"},{"key":"B","text":"两支同时烧得更旺"},{"key":"C","text":"下层蜡烛"},{"key":"D","text":"杯外的蜡烛"}],"a":"C","ex":"二氧化碳密度比空气大，先聚集在下部，下层蜡烛先熄灭。"},{"id":"cnk_j024_q3","tid":"cnk_j024","ty":"choice","df":"standard","p":"把生成的气体通入澄清石灰水，石灰水变浑浊，说明气体是？","ch":[{"key":"A","text":"氧气"},{"key":"B","text":"氢气"},{"key":"C","text":"氮气"},{"key":"D","text":"二氧化碳"}],"a":"D","ex":"二氧化碳与氢氧化钙反应生成碳酸钙沉淀，石灰水变浑浊。"},{"id":"cnk_j024_q4","tid":"cnk_j024","ty":"choice","df":"challenge","p":"实验使用稀盐酸而不是浓盐酸，主要是为了？","ch":[{"key":"A","text":"减少氯化氢挥发带来的白雾，使气体更纯净"},{"key":"B","text":"让反应完全不发生"},{"key":"C","text":"把二氧化碳变成一氧化碳"},{"key":"D","text":"使大理石不与酸接触"}],"a":"A","ex":"浓盐酸易挥发，挥发出的氯化氢会混入二氧化碳。"},{"id":"cnk_j025_q1","tid":"cnk_j025","ty":"choice","df":"basic","p":"燃烧需要同时满足的条件是？","ch":[{"key":"A","text":"只要有可燃物"},{"key":"B","text":"只要温度很高，没有氧气也能燃烧"},{"key":"C","text":"可燃物、与氧气接触、温度达到着火点"},{"key":"D","text":"只要与水接触"}],"a":"C","ex":"三个条件缺一不可。"},{"id":"cnk_j025_q2","tid":"cnk_j025","ty":"choice","df":"basic","p":"油锅里的油着火，较合适的做法是？","ch":[{"key":"A","text":"用水浇灭"},{"key":"B","text":"把油倒进水槽"},{"key":"C","text":"打开窗户让风把火吹旺"},{"key":"D","text":"盖上锅盖"}],"a":"D","ex":"盖上锅盖隔绝空气。水可能使热油飞溅。"},{"id":"cnk_j025_q3","tid":"cnk_j025","ty":"choice","df":"standard","p":"白磷保存在水中，是因为？","ch":[{"key":"A","text":"水能隔绝空气，避免白磷与氧气接触而燃烧"},{"key":"B","text":"水能升高白磷的着火点"},{"key":"C","text":"白磷不能作可燃物"},{"key":"D","text":"水能提供燃烧需要的氧气"}],"a":"A","ex":"白磷着火点较低，保存在水中是为了隔绝氧气。这里不记具体温度数字。"},{"id":"cnk_j025_q4","tid":"cnk_j025","ty":"choice","df":"challenge","p":"灭火的原理可以是？","ch":[{"key":"A","text":"必须三个条件同时加强"},{"key":"B","text":"清除可燃物、隔绝空气或使温度降到着火点以下"},{"key":"C","text":"只增加氧气"},{"key":"D","text":"把着火点暂时升高到任意高温仍继续供氧"}],"a":"B","ex":"去掉燃烧条件中的任意一个，火就会熄灭。"},{"id":"cnk_j026_q1","tid":"cnk_j026","ty":"choice","df":"basic","p":"煤、石油、天然气属于？","ch":[{"key":"A","text":"取之不尽的能源"},{"key":"B","text":"都是单质碳"},{"key":"C","text":"使用时一定不产生任何气体"},{"key":"D","text":"化石能源，在短期内不能再生"}],"a":"D","ex":"化石能源由古代生物遗骸经过漫长变化形成，不能在短时间内再生。"},{"id":"cnk_j026_q2","tid":"cnk_j026","ty":"choice","df":"basic","p":"石油分馏得到汽油、柴油等，这一过程主要是？","ch":[{"key":"A","text":"物理变化"},{"key":"B","text":"把石油变成了新的元素"},{"key":"C","text":"分解反应，生成了氢气作为唯一产物"},{"key":"D","text":"使石油完全变成碳单质"}],"a":"A","ex":"分馏是利用沸点不同把混合物分离，没有生成新物质，主要是物理变化。"},{"id":"cnk_j026_q3","tid":"cnk_j026","ty":"choice","df":"standard","p":"燃料不完全燃烧，容易产生的有害气体是？","ch":[{"key":"A","text":"只有二氧化碳和水"},{"key":"B","text":"一氧化碳"},{"key":"C","text":"氧气"},{"key":"D","text":"氮气"}],"a":"B","ex":"氧气不足时，碳燃烧容易生成有毒的一氧化碳。充分燃烧主要生成二氧化碳。"},{"id":"cnk_j026_q4","tid":"cnk_j026","ty":"choice","df":"challenge","p":"下列做法符合合理利用能源的是？","ch":[{"key":"A","text":"让煤在敞开环境中慢慢冒烟"},{"key":"B","text":"把所有塑料都当煤烧掉"},{"key":"C","text":"选用燃烧效率较高的炉具，并减少不必要的燃料消耗"},{"key":"D","text":"认为化石能源用完还可以在几个月内重新生成"}],"a":"C","ex":"充分燃烧、节约使用，能减少浪费和有害气体。化石能源不能在短期内再生。"},{"id":"cnk_j027_q1","tid":"cnk_j027","ty":"choice","df":"basic","p":"铜片上的白磷燃烧、红磷不燃烧，水中的白磷不燃烧。这个实验说明燃烧需要？","ch":[{"key":"A","text":"温度达到着火点，并且与氧气接触"},{"key":"B","text":"只需要可燃物"},{"key":"C","text":"白磷不是可燃物"},{"key":"D","text":"水能提供氧气"}],"a":"A","ex":"热水使白磷达到着火点而红磷未达到；水中的白磷接触不到氧气。"},{"id":"cnk_j027_q2","tid":"cnk_j027","ty":"choice","df":"basic","p":"做这个实验时，应控制？","ch":[{"key":"A","text":"同时改变温度、可燃物和是否接触氧气"},{"key":"B","text":"可燃物种类或接触的气体，一次只改变一个条件"},{"key":"C","text":"不观察水中的白磷"},{"key":"D","text":"先把两种磷都点燃再比较"}],"a":"B","ex":"对照实验一次只改变一个条件，才能说明是哪一个条件起作用。"},{"id":"cnk_j027_q3","tid":"cnk_j027","ty":"choice","df":"standard","p":"红磷和白磷都是可燃物。热水中只有铜片上的白磷燃烧，是因为？","ch":[{"key":"A","text":"它浸在水里"},{"key":"B","text":"红磷的着火点更低"},{"key":"C","text":"它与氧气接触，且温度达到了它的着火点"},{"key":"D","text":"铜片能燃烧"}],"a":"C","ex":"白磷着火点比红磷低。题中不使用具体温度。铜片上的白磷接触空气，水中的白磷不接触氧气。"},{"id":"cnk_j027_q4","tid":"cnk_j027","ty":"choice","df":"challenge","p":"实验后若白磷仍有剩余，应当？","ch":[{"key":"A","text":"倒进水槽冲走"},{"key":"B","text":"放进书包"},{"key":"C","text":"在空气中继续点燃玩"},{"key":"D","text":"按实验室要求回收，不随意丢弃或带出实验室"}],"a":"D","ex":"白磷易燃且有毒，必须按实验室规定处理。"},{"id":"cnk_j028_q1","tid":"cnk_j028","ty":"choice","df":"basic","p":"多数金属共有的物理性质是？","ch":[{"key":"A","text":"常温下都是气体"},{"key":"B","text":"有金属光泽，能导电、导热，有延展性"},{"key":"C","text":"都不能导电"},{"key":"D","text":"都极易溶于水"}],"a":"B","ex":"金属一般有光泽、导电、导热、延展性。汞在常温下是液体，是少数例外。"},{"id":"cnk_j028_q2","tid":"cnk_j028","ty":"choice","df":"basic","p":"钢是？","ch":[{"key":"A","text":"一种纯净的铁单质"},{"key":"B","text":"铜和铝的混合物，不含铁"},{"key":"C","text":"铁的合金"},{"key":"D","text":"非金属材料"}],"a":"C","ex":"钢是含碳等元素的铁合金，硬度通常比纯铁大。"},{"id":"cnk_j028_q3","tid":"cnk_j028","ty":"choice","df":"standard","p":"做导线常用铜，主要利用铜的？","ch":[{"key":"A","text":"密度比铝小"},{"key":"B","text":"不能传热"},{"key":"C","text":"在空气中极易燃烧"},{"key":"D","text":"导电性好、延展性好"}],"a":"D","ex":"铜容易拉成丝，导电性良好。"},{"id":"cnk_j028_q4","tid":"cnk_j028","ty":"choice","df":"challenge","p":"下列物质在常温下是液态的金属是？","ch":[{"key":"A","text":"汞"},{"key":"B","text":"铁"},{"key":"C","text":"铜"},{"key":"D","text":"铝"}],"a":"A","ex":"汞是常温下常见的液态金属。铁、铜、铝常温下是固体。"},{"id":"cnk_j029_q1","tid":"cnk_j029","ty":"choice","df":"basic","p":"铝在空气中不易继续被腐蚀，主要因为？","ch":[{"key":"A","text":"铝的活动性比金还弱"},{"key":"B","text":"铝不与氧气反应"},{"key":"C","text":"表面生成致密的氧化膜"},{"key":"D","text":"铝是非金属"}],"a":"C","ex":"铝比较活泼，但致密的氧化铝薄膜能阻止内部继续氧化。"},{"id":"cnk_j029_q2","tid":"cnk_j029","ty":"choice","df":"basic","p":"把锌粒放入稀硫酸，产生的气体是？","ch":[{"key":"A","text":"氧气"},{"key":"B","text":"二氧化碳"},{"key":"C","text":"二氧化硫"},{"key":"D","text":"氢气"}],"a":"D","ex":"锌与稀硫酸反应生成硫酸锌和氢气。"},{"id":"cnk_j029_q3","tid":"cnk_j029","ty":"choice","df":"standard","p":"铜放入稀盐酸中，通常？","ch":[{"key":"A","text":"不产生氢气"},{"key":"B","text":"迅速产生大量氢气"},{"key":"C","text":"生成绿色的氯化铜溶液并放出氢气"},{"key":"D","text":"立刻全部溶解并燃烧"}],"a":"A","ex":"铜排在氢后面，不能置换出稀盐酸中的氢。"},{"id":"cnk_j029_q4","tid":"cnk_j029","ty":"choice","df":"challenge","p":"铁与稀盐酸反应，生成的盐是？","ch":[{"key":"A","text":"氯化铁"},{"key":"B","text":"氯化亚铁"},{"key":"C","text":"氧化铁"},{"key":"D","text":"碳酸亚铁"}],"a":"B","ex":"铁与稀盐酸反应生成氯化亚铁和氢气，溶液呈浅绿色，不是氯化铁。"},{"id":"cnk_j030_q1","tid":"cnk_j030","ty":"choice","df":"basic","p":"金属活动性顺序里，排在氢前面的金属？","ch":[{"key":"A","text":"都不能与酸反应"},{"key":"B","text":"只能与盐反应、不能与酸反应"},{"key":"C","text":"一定不与氧气反应"},{"key":"D","text":"能与稀盐酸或稀硫酸反应产生氢气"}],"a":"D","ex":"氢前金属能置换出酸中的氢。钾、钙、钠还会与水剧烈反应，不能随意投入酸中。"},{"id":"cnk_j030_q2","tid":"cnk_j030","ty":"choice","df":"basic","p":"把铁钉放入硫酸铜溶液，可以观察到？","ch":[{"key":"A","text":"铁表面覆盖红色固体，溶液蓝色变浅"},{"key":"B","text":"铁表面产生大量气泡且溶液仍为深蓝色不变"},{"key":"C","text":"没有任何变化"},{"key":"D","text":"析出银白色金属钠"}],"a":"A","ex":"铁比铜活泼，能把铜从硫酸铜溶液中置换出来。"},{"id":"cnk_j030_q3","tid":"cnk_j030","ty":"choice","df":"standard","p":"下列金属能与稀硫酸反应产生氢气的是？","ch":[{"key":"A","text":"铜"},{"key":"B","text":"锌"},{"key":"C","text":"银"},{"key":"D","text":"金"}],"a":"B","ex":"锌在氢前，铜、银、金在氢后。"},{"id":"cnk_j030_q4","tid":"cnk_j030","ty":"choice","df":"challenge","p":"要验证锌、铜、银的活动性顺序，下列试剂组合可行的是？","ch":[{"key":"A","text":"只有铜和银"},{"key":"B","text":"只有稀硫酸"},{"key":"C","text":"锌、银和硫酸铜溶液"},{"key":"D","text":"金和硫酸铜溶液"}],"a":"C","ex":"锌能置换出硫酸铜中的铜，银不能。由此得到锌比铜活泼、铜比银活泼。"},{"id":"cnk_j031_q1","tid":"cnk_j031","ty":"choice","df":"basic","p":"铁生锈需要的主要条件是？","ch":[{"key":"A","text":"与氧气和水同时接触"},{"key":"B","text":"只与干燥的氧气接触"},{"key":"C","text":"只浸在煮沸后密封的水中"},{"key":"D","text":"与氮气接触"}],"a":"A","ex":"铁在潮湿空气中容易生锈。隔绝氧气或水都能减慢生锈。"},{"id":"cnk_j031_q2","tid":"cnk_j031","ty":"choice","df":"basic","p":"下列方法能防止铁制品生锈的是？","ch":[{"key":"A","text":"长期放在潮湿空气中"},{"key":"B","text":"涂漆或涂油"},{"key":"C","text":"用盐水浸泡"},{"key":"D","text":"把表面打磨后淋雨"}],"a":"B","ex":"涂漆、涂油能隔绝空气和水。"},{"id":"cnk_j031_q3","tid":"cnk_j031","ty":"choice","df":"standard","p":"炼铁时，一氧化碳与氧化铁在高温下反应，生成？","ch":[{"key":"A","text":"只有氧气"},{"key":"B","text":"碳和水"},{"key":"C","text":"铁和二氧化碳"},{"key":"D","text":"氧化铁不变化"}],"a":"C","ex":"一氧化碳夺取氧化铁中的氧，生成铁和二氧化碳。"},{"id":"cnk_j031_q4","tid":"cnk_j031","ty":"choice","df":"challenge","p":"回收废旧金属的意义是？","ch":[{"key":"A","text":"金属用完几个月就能在矿里重新长出"},{"key":"B","text":"废金属不能再冶炼"},{"key":"C","text":"回收一定会增加锈蚀"},{"key":"D","text":"节约金属资源和能源，减少污染"}],"a":"D","ex":"金属矿物有限。回收能少采矿、少炼矿，并减少废弃物。"},{"id":"cnk_j032_q1","tid":"cnk_j032","ty":"choice","df":"basic","p":"比较镁、铁、铜与同浓度稀盐酸的反应，产生气泡由快到慢，说明活动性？","ch":[{"key":"A","text":"铜大于铁大于镁"},{"key":"B","text":"镁大于铁大于铜"},{"key":"C","text":"三者相同"},{"key":"D","text":"铜能置换出酸中的氢而镁不能"}],"a":"B","ex":"与酸反应越剧烈，通常活动性越强。铜与稀盐酸不产生氢气。"},{"id":"cnk_j032_q2","tid":"cnk_j032","ty":"choice","df":"basic","p":"实验中，铁钉放入硫酸铜溶液，铁钉表面出现红色物质。该物质是？","ch":[{"key":"A","text":"氧化铁"},{"key":"B","text":"银"},{"key":"C","text":"铜"},{"key":"D","text":"炭"}],"a":"C","ex":"铁置换出了铜，红色固体是铜。"},{"id":"cnk_j032_q3","tid":"cnk_j032","ty":"choice","df":"standard","p":"试验金属能否导电时，应当？","ch":[{"key":"A","text":"用手触摸正在加热的金属"},{"key":"B","text":"把金属投入浓酸后品尝"},{"key":"C","text":"只看颜色"},{"key":"D","text":"把金属接入电路，看小灯泡是否发光"}],"a":"D","ex":"金属导电时，串联的小灯泡会发光。不能品尝酸，也不要用手摸热金属。"},{"id":"cnk_j032_q4","tid":"cnk_j032","ty":"choice","df":"challenge","p":"做完酸与金属的实验，剩余的酸应？","ch":[{"key":"A","text":"倒入指定的废液缸"},{"key":"B","text":"倒回原瓶"},{"key":"C","text":"倒进水槽"},{"key":"D","text":"带出实验室"}],"a":"A","ex":"剩余酸液按实验室规定倒入废液缸，不能倒回原瓶。"},{"id":"cnk_j033_q1","tid":"cnk_j033","ty":"choice","df":"basic","p":"溶液的特征是？","ch":[{"key":"A","text":"静置后一定会分层"},{"key":"B","text":"一定是无色的"},{"key":"C","text":"均一、稳定的混合物"},{"key":"D","text":"属于纯净物"}],"a":"C","ex":"溶液各处浓度相同，稳定，不易分层。溶液可以有颜色，例如硫酸铜溶液。"},{"id":"cnk_j033_q2","tid":"cnk_j033","ty":"choice","df":"basic","p":"蔗糖溶于水，蔗糖是？","ch":[{"key":"A","text":"溶剂"},{"key":"B","text":"溶液"},{"key":"C","text":"乳浊液"},{"key":"D","text":"溶质"}],"a":"D","ex":"被溶解的蔗糖是溶质，水是溶剂，得到的是蔗糖溶液。"},{"id":"cnk_j033_q3","tid":"cnk_j033","ty":"choice","df":"standard","p":"泥土放入水中搅拌后得到的是？","ch":[{"key":"A","text":"悬浊液"},{"key":"B","text":"溶液"},{"key":"C","text":"纯净物"},{"key":"D","text":"化合物"}],"a":"A","ex":"泥土的固体小颗粒悬浮在水中，静置后会下沉，是悬浊液，不是溶液。"},{"id":"cnk_j033_q4","tid":"cnk_j033","ty":"choice","df":"challenge","p":"碘酒是碘溶解在酒精中形成的，它属于？","ch":[{"key":"A","text":"悬浊液"},{"key":"B","text":"溶液"},{"key":"C","text":"乳浊液"},{"key":"D","text":"单质"}],"a":"B","ex":"碘是溶质，酒精是溶剂，碘酒是溶液。溶剂不一定是水。"},{"id":"cnk_j034_q1","tid":"cnk_j034","ty":"choice","df":"basic","p":"固体溶解度的含义是？","ch":[{"key":"A","text":"任何温度下都能溶解的质量"},{"key":"B","text":"100 g 溶液里溶质的质量"},{"key":"C","text":"溶剂的质量"},{"key":"D","text":"一定温度下，100 g 溶剂中达到饱和时溶解的溶质质量"}],"a":"D","ex":"溶解度必须指明温度，并且是 100 g 溶剂、饱和状态。"},{"id":"cnk_j034_q2","tid":"cnk_j034","ty":"choice","df":"basic","p":"多数固体物质的溶解度随温度升高而？","ch":[{"key":"A","text":"增大"},{"key":"B","text":"一定减小"},{"key":"C","text":"不变"},{"key":"D","text":"变为 0"}],"a":"A","ex":"多数固体升温后溶解度增大。气体一般相反。氢氧化钙是固体中的常见例外，溶解度随温度升高而减小。"},{"id":"cnk_j034_q3","tid":"cnk_j034","ty":"numeric","df":"standard","p":"20 ℃ 时某物质溶解度为 36 g。该温度下 50 g 水中最多能溶解这种物质多少克？","a":"18","ex":"50 g 水是 100 g 水的一半，最多溶解 18 g。"},{"id":"cnk_j034_q4","tid":"cnk_j034","ty":"choice","df":"challenge","p":"打开汽水瓶盖有气泡冒出，主要因为？","ch":[{"key":"A","text":"温度突然降到 0 ℃ 以下"},{"key":"B","text":"水变成了二氧化碳"},{"key":"C","text":"压强减小，二氧化碳的溶解度减小"},{"key":"D","text":"溶质全部变成了沉淀"}],"a":"C","ex":"气体溶解度随压强减小而减小，溶解的二氧化碳逸出。"},{"id":"cnk_j035_q1","tid":"cnk_j035","ty":"choice","df":"basic","p":"溶质的质量分数等于？","ch":[{"key":"A","text":"溶质质量除以溶液质量"},{"key":"B","text":"溶质质量除以溶剂质量"},{"key":"C","text":"溶剂质量除以溶质质量"},{"key":"D","text":"溶液质量除以溶质质量"}],"a":"A","ex":"分母是溶液质量，溶液质量等于溶质质量加溶剂质量。"},{"id":"cnk_j035_q2","tid":"cnk_j035","ty":"choice","df":"basic","p":"把 10 g 氯化钠溶于水，配成 100 g 溶液。溶质的质量分数是？","ch":[{"key":"A","text":"1%"},{"key":"B","text":"10%"},{"key":"C","text":"90%"},{"key":"D","text":"100%"}],"a":"B","ex":"10 除以 100 等于 10%。不能用 10 除以 90。"},{"id":"cnk_j035_q3","tid":"cnk_j035","ty":"numeric","df":"standard","p":"要配制 100 g 质量分数为 10% 的氯化钠溶液，需要氯化钠多少克？","a":"10","ex":"100 乘 10% 等于 10 g。其余 90 g 是水。"},{"id":"cnk_j035_q4","tid":"cnk_j035","ty":"numeric","df":"challenge","p":"要配制 150 g 质量分数为 4% 的氯化钠溶液，需要氯化钠多少克？","a":"6","ex":"150 乘 4% 等于 6 g。"},{"id":"cnk_j036_q1","tid":"cnk_j036","ty":"choice","df":"basic","p":"配制溶液时，称量氯化钠常用？","ch":[{"key":"A","text":"只用量筒量取固体的体积当成质量"},{"key":"B","text":"托盘天平"},{"key":"C","text":"用温度计称量"},{"key":"D","text":"用漏斗直接称"}],"a":"B","ex":"固体用天平称量，水用量筒量取。"},{"id":"cnk_j036_q2","tid":"cnk_j036","ty":"choice","df":"basic","p":"量取水时，读数应？","ch":[{"key":"A","text":"俯视凹液面"},{"key":"B","text":"仰视刻度线以上"},{"key":"C","text":"视线与量筒内液体凹液面的最低处保持水平"},{"key":"D","text":"读取玻璃棒上的刻度"}],"a":"C","ex":"俯视会使读数偏大，仰视会使读数偏小。"},{"id":"cnk_j036_q3","tid":"cnk_j036","ty":"choice","df":"standard","p":"溶解时用玻璃棒搅拌，是为了？","ch":[{"key":"A","text":"把烧杯搅拌破"},{"key":"B","text":"增加溶质质量"},{"key":"C","text":"使溶液质量分数变大"},{"key":"D","text":"加快溶解"}],"a":"D","ex":"搅拌加快溶解，不改变已经称好的溶质和溶剂质量。"},{"id":"cnk_j036_q4","tid":"cnk_j036","ty":"numeric","df":"challenge","p":"计算需要 90 g 水。若水的密度按 1 g/mL 计，应量取水多少毫升？","a":"90","ex":"90 g 水的体积约是 90 mL。"},{"id":"cnk_j037_q1","tid":"cnk_j037","ty":"choice","df":"basic","p":"除去粗盐中的泥沙，正确的顺序是？","ch":[{"key":"A","text":"先蒸发再过滤"},{"key":"B","text":"只加热不溶解"},{"key":"C","text":"溶解、过滤、蒸发"},{"key":"D","text":"先过滤固体再加水"}],"a":"C","ex":"先把可溶的盐溶进水里，滤去泥沙，再蒸发得到食盐。"},{"id":"cnk_j037_q2","tid":"cnk_j037","ty":"choice","df":"basic","p":"过滤时，液面应？","ch":[{"key":"A","text":"高于滤纸边缘，让液体从滤纸外流下"},{"key":"B","text":"与漏斗口平齐并漫出"},{"key":"C","text":"不用滤纸"},{"key":"D","text":"低于滤纸边缘"}],"a":"D","ex":"液面高于滤纸边缘，液体会从滤纸与漏斗的间隙流下，过滤失败。"},{"id":"cnk_j037_q3","tid":"cnk_j037","ty":"choice","df":"standard","p":"蒸发食盐溶液时，出现较多固体后应？","ch":[{"key":"A","text":"停止加热，用余热蒸干"},{"key":"B","text":"把蒸发皿直接用手拿下来"},{"key":"C","text":"继续强热到全部烧红"},{"key":"D","text":"立即加入稀硫酸"}],"a":"A","ex":"余热可以蒸干剩余少量液体。热的蒸发皿要用坩埚钳取。"},{"id":"cnk_j037_q4","tid":"cnk_j037","ty":"choice","df":"challenge","p":"这一套操作不能除去的是？","ch":[{"key":"A","text":"泥沙"},{"key":"B","text":"溶解在水里的可溶性杂质"},{"key":"C","text":"不溶于水的沙粒"},{"key":"D","text":"滤纸上留下的固体"}],"a":"B","ex":"过滤除去的是不溶性杂质。溶解的可溶性杂质仍留在蒸发后的固体里。"},{"id":"cnk_j038_q1","tid":"cnk_j038","ty":"choice","df":"basic","p":"pH 小于 7 的溶液呈？","ch":[{"key":"A","text":"碱性"},{"key":"B","text":"中性"},{"key":"C","text":"一定不能使指示剂变色"},{"key":"D","text":"酸性"}],"a":"D","ex":"pH 小于 7 为酸性，等于 7 为中性，大于 7 为碱性。"},{"id":"cnk_j038_q2","tid":"cnk_j038","ty":"choice","df":"basic","p":"紫色石蕊试液遇酸性溶液变为？","ch":[{"key":"A","text":"红色"},{"key":"B","text":"蓝色"},{"key":"C","text":"无色"},{"key":"D","text":"紫色不变"}],"a":"A","ex":"石蕊遇酸变红，遇碱变蓝。酚酞遇酸仍为无色，遇碱变红。"},{"id":"cnk_j038_q3","tid":"cnk_j038","ty":"choice","df":"standard","p":"酚酞试液滴入氢氧化钠溶液中，现象是？","ch":[{"key":"A","text":"变蓝"},{"key":"B","text":"变红"},{"key":"C","text":"先变红再一定变蓝"},{"key":"D","text":"没有颜色变化"}],"a":"B","ex":"氢氧化钠溶液呈碱性，酚酞变红。"},{"id":"cnk_j038_q4","tid":"cnk_j038","ty":"choice","df":"challenge","p":"下列液体中，pH 最可能大于 7 的是？","ch":[{"key":"A","text":"白醋"},{"key":"B","text":"稀盐酸"},{"key":"C","text":"肥皂水"},{"key":"D","text":"食盐水"}],"a":"C","ex":"肥皂水呈碱性。白醋和稀盐酸呈酸性。食盐水接近中性。"},{"id":"cnk_j039_q1","tid":"cnk_j039","ty":"choice","df":"basic","p":"稀盐酸中滴入紫色石蕊试液，溶液变为？","ch":[{"key":"A","text":"红色"},{"key":"B","text":"蓝色"},{"key":"C","text":"无色后立刻变蓝"},{"key":"D","text":"没有变化"}],"a":"A","ex":"酸溶液使石蕊变红。"},{"id":"cnk_j039_q2","tid":"cnk_j039","ty":"choice","df":"basic","p":"铁锈的主要成分能与稀盐酸反应。反应后铁锈减少，是因为？","ch":[{"key":"A","text":"盐酸把铁变成了铜"},{"key":"B","text":"氧化铁与盐酸反应生成可溶的氯化铁"},{"key":"C","text":"铁锈是泥沙，被过滤除去"},{"key":"D","text":"盐酸只发生了物理溶解"}],"a":"B","ex":"氧化铁与盐酸反应生成氯化铁和水，所以锈斑被除去。"},{"id":"cnk_j039_q3","tid":"cnk_j039","ty":"choice","df":"standard","p":"浓硫酸沾到皮肤上，正确的处理是？","ch":[{"key":"A","text":"用少量水抹一下继续实验"},{"key":"B","text":"用碱直接在皮肤上中和而不冲洗"},{"key":"C","text":"立即用大量水冲洗，再请医生处理"},{"key":"D","text":"不予处理"}],"a":"C","ex":"先用大量水冲洗。稀释浓硫酸时也要把酸慢慢加入水中。"},{"id":"cnk_j039_q4","tid":"cnk_j039","ty":"choice","df":"challenge","p":"下列物质能与稀硫酸反应产生氢气的是？","ch":[{"key":"A","text":"铜"},{"key":"B","text":"银"},{"key":"C","text":"碳"},{"key":"D","text":"锌"}],"a":"D","ex":"锌在金属活动性顺序中位于氢前。铜和银不能置换出酸中的氢。"},{"id":"cnk_j040_q1","tid":"cnk_j040","ty":"choice","df":"basic","p":"氢氧化钠露置在空气中容易潮解，保存时应？","ch":[{"key":"A","text":"敞口放在窗台"},{"key":"B","text":"密封"},{"key":"C","text":"配成溶液后不盖瓶塞长期放置"},{"key":"D","text":"与酸混放在同一只敞口烧杯"}],"a":"B","ex":"氢氧化钠易潮解，还会与空气中的二氧化碳反应，必须密封保存。"},{"id":"cnk_j040_q2","tid":"cnk_j040","ty":"choice","df":"basic","p":"澄清石灰水露置在空气中变浑浊，是因为？","ch":[{"key":"A","text":"水蒸发后只剩下氢氧化钠"},{"key":"B","text":"石灰水变成了盐酸"},{"key":"C","text":"氢氧化钙与二氧化碳反应生成碳酸钙"},{"key":"D","text":"二氧化碳使它变成了酚酞"}],"a":"C","ex":"生成的碳酸钙难溶于水，所以变浑浊。这也是检验二氧化碳的原理。"},{"id":"cnk_j040_q3","tid":"cnk_j040","ty":"choice","df":"standard","p":"氢氧化钠溶液沾到手上，应？","ch":[{"key":"A","text":"任其干燥"},{"key":"B","text":"用嘴吹干"},{"key":"C","text":"涂上浓硫酸"},{"key":"D","text":"立即用大量水冲洗"}],"a":"D","ex":"氢氧化钠有强腐蚀性，要立刻大量冲洗。"},{"id":"cnk_j040_q4","tid":"cnk_j040","ty":"choice","df":"challenge","p":"下列物质属于碱的是？","ch":[{"key":"A","text":"氢氧化钙"},{"key":"B","text":"氯化钠"},{"key":"C","text":"碳酸钠"},{"key":"D","text":"硫酸"}],"a":"A","ex":"氢氧化钙是碱。氯化钠和碳酸钠是盐，硫酸是酸。"},{"id":"cnk_j041_q1","tid":"cnk_j041","ty":"choice","df":"basic","p":"中和反应是？","ch":[{"key":"A","text":"任何两种物质混合"},{"key":"B","text":"盐与金属的反应"},{"key":"C","text":"酸与碱作用生成盐和水"},{"key":"D","text":"只指酸与活泼金属产生氢气"}],"a":"C","ex":"酸和碱生成盐和水，才是中和反应。"},{"id":"cnk_j041_q2","tid":"cnk_j041","ty":"choice","df":"basic","p":"盐酸与氢氧化钠反应的生成物是？","ch":[{"key":"A","text":"只有氢气"},{"key":"B","text":"碳酸钠"},{"key":"C","text":"氯化铁"},{"key":"D","text":"氯化钠和水"}],"a":"D","ex":"HCl 与 NaOH 反应生成 NaCl 和 H2O。"},{"id":"cnk_j041_q3","tid":"cnk_j041","ty":"choice","df":"standard","p":"土壤酸性太强时，可以适量施加？","ch":[{"key":"A","text":"熟石灰"},{"key":"B","text":"稀盐酸"},{"key":"C","text":"食盐代替所有肥料"},{"key":"D","text":"硫酸"}],"a":"A","ex":"熟石灰是氢氧化钙，能中和土壤中的酸。不能用强酸去“中和”酸性土壤。"},{"id":"cnk_j041_q4","tid":"cnk_j041","ty":"choice","df":"challenge","p":"在滴有酚酞的氢氧化钠溶液中逐滴加入稀盐酸，红色刚好消失。此时溶液中的溶质主要是？","ch":[{"key":"A","text":"氢氧化钠"},{"key":"B","text":"氯化钠"},{"key":"C","text":"盐酸和氢氧化钠都大量剩余"},{"key":"D","text":"碳酸钙"}],"a":"B","ex":"酚酞刚好变为无色，说明碱已被酸中和，生成的盐是氯化钠。"},{"id":"cnk_j042_q1","tid":"cnk_j042","ty":"choice","df":"basic","p":"食盐的主要成分是？","ch":[{"key":"A","text":"氢氧化钠"},{"key":"B","text":"碳酸钠"},{"key":"C","text":"硫酸"},{"key":"D","text":"氯化钠"}],"a":"D","ex":"食盐的主要成分是氯化钠，它是盐，不是碱。"},{"id":"cnk_j042_q2","tid":"cnk_j042","ty":"choice","df":"basic","p":"下列物质属于盐的是？","ch":[{"key":"A","text":"碳酸钙"},{"key":"B","text":"氢氧化钙"},{"key":"C","text":"稀盐酸"},{"key":"D","text":"氧气"}],"a":"A","ex":"碳酸钙由金属离子和酸根离子构成，是盐。氢氧化钙是碱。"},{"id":"cnk_j042_q3","tid":"cnk_j042","ty":"choice","df":"standard","p":"碳酸钠溶液滴入酚酞后变红，说明该溶液？","ch":[{"key":"A","text":"呈酸性"},{"key":"B","text":"呈碱性"},{"key":"C","text":"是单质"},{"key":"D","text":"不能导电"}],"a":"B","ex":"碳酸钠是盐，它的溶液呈碱性，能使酚酞变红。"},{"id":"cnk_j042_q4","tid":"cnk_j042","ty":"choice","df":"challenge","p":"铵态氮肥与熟石灰混合研磨，产生刺激性气味的气体。该气体是？","ch":[{"key":"A","text":"氧气"},{"key":"B","text":"氢气"},{"key":"C","text":"氨气"},{"key":"D","text":"二氧化碳"}],"a":"C","ex":"铵盐与碱混合会放出氨气，所以铵态氮肥不要与碱性物质混合施用。"},{"id":"cnk_j043_q1","tid":"cnk_j043","ty":"choice","df":"basic","p":"把稀盐酸分别滴到紫色石蕊和酚酞上，现象是？","ch":[{"key":"A","text":"石蕊变红，酚酞仍为无色"},{"key":"B","text":"两者都变蓝"},{"key":"C","text":"石蕊变蓝，酚酞变红"},{"key":"D","text":"两者都没有变化"}],"a":"A","ex":"酸使石蕊变红，不能使酚酞变红。"},{"id":"cnk_j043_q2","tid":"cnk_j043","ty":"choice","df":"basic","p":"稀盐酸与氧化铜反应，溶液变为？","ch":[{"key":"A","text":"红色"},{"key":"B","text":"蓝色"},{"key":"C","text":"仍无色且氧化铜不减少"},{"key":"D","text":"紫色"}],"a":"B","ex":"氧化铜与盐酸反应生成氯化铜，氯化铜溶液呈蓝色。"},{"id":"cnk_j043_q3","tid":"cnk_j043","ty":"choice","df":"standard","p":"在盛有氢氧化钠溶液的试管中先滴酚酞，再逐滴加入稀盐酸至过量。颜色变化是？","ch":[{"key":"A","text":"先变蓝，后变红"},{"key":"B","text":"一直无色"},{"key":"C","text":"先变红，后褪去"},{"key":"D","text":"先无色，后变蓝且不再变化"}],"a":"C","ex":"碱使酚酞变红；酸把碱中和后，红色消失。酸过量时酚酞仍为无色。"},{"id":"cnk_j043_q4","tid":"cnk_j043","ty":"choice","df":"challenge","p":"实验中取用稀酸、稀碱后，滴管应？","ch":[{"key":"A","text":"在酸瓶和碱瓶之间来回使用同一支不洗的滴管"},{"key":"B","text":"放在桌面上滚动"},{"key":"C","text":"用嘴吹掉残留液体"},{"key":"D","text":"分别清洗或专用，不能混用后放回原瓶"}],"a":"D","ex":"混用滴管会污染试剂，也可能在瓶内发生反应。"},{"id":"cnk_j044_q1","tid":"cnk_j044","ty":"choice","df":"basic","p":"人体所需的营养物质包括？","ch":[{"key":"A","text":"只有蛋白质和水"},{"key":"B","text":"蛋白质、糖类、油脂、维生素、无机盐和水"},{"key":"C","text":"只有维生素"},{"key":"D","text":"只有食盐"}],"a":"B","ex":"六类营养物质都需要，不能只吃其中一类。"},{"id":"cnk_j044_q2","tid":"cnk_j044","ty":"choice","df":"basic","p":"儿童缺钙，主要可能影响？","ch":[{"key":"A","text":"只影响视力中的夜盲"},{"key":"B","text":"只影响甲状腺"},{"key":"C","text":"骨骼和牙齿的发育"},{"key":"D","text":"血红蛋白完全不能含铁"}],"a":"C","ex":"钙是构成骨骼和牙齿的重要元素。缺铁影响血红蛋白，缺碘影响甲状腺。"},{"id":"cnk_j044_q3","tid":"cnk_j044","ty":"choice","df":"standard","p":"缺乏维生素 C，容易患？","ch":[{"key":"A","text":"佝偻病"},{"key":"B","text":"夜盲症"},{"key":"C","text":"贫血"},{"key":"D","text":"坏血病"}],"a":"D","ex":"维生素 C 缺乏容易患坏血病。维生素 D 与佝偻病、维生素 A 与夜盲症有关。"},{"id":"cnk_j044_q4","tid":"cnk_j044","ty":"choice","df":"challenge","p":"下列做法有利于健康的是？","ch":[{"key":"A","text":"膳食多样，不偏食"},{"key":"B","text":"只吃肉类，不吃蔬菜"},{"key":"C","text":"用饮料代替所有饮水"},{"key":"D","text":"把霉变食物洗一下继续吃"}],"a":"A","ex":"不同食物提供的营养不同。霉变食物可能含有有害物质，不应食用。"},{"id":"cnk_j045_q1","tid":"cnk_j045","ty":"choice","df":"basic","p":"塑料、合成纤维和合成橡胶属于？","ch":[{"key":"A","text":"天然存在的矿石"},{"key":"B","text":"都是金属合金"},{"key":"C","text":"合成材料"},{"key":"D","text":"都是肥料"}],"a":"C","ex":"这三类是常见的有机合成材料。"},{"id":"cnk_j045_q2","tid":"cnk_j045","ty":"choice","df":"basic","p":"使用塑料方便生活，同时也要？","ch":[{"key":"A","text":"把所有塑料就地焚烧而不处理烟气"},{"key":"B","text":"生产得越多越好，不必回收"},{"key":"C","text":"认为塑料在土壤里几天就一定消失"},{"key":"D","text":"减少随意丢弃，分类回收"}],"a":"D","ex":"随意丢弃塑料会造成白色污染。回收利用能减少资源消耗。"},{"id":"cnk_j045_q3","tid":"cnk_j045","ty":"choice","df":"standard","p":"下列做法更符合可持续发展的是？","ch":[{"key":"A","text":"研制污染更少的生产流程，并节约能源和原料"},{"key":"B","text":"只增加产量，不处理废水和废气"},{"key":"C","text":"把化石能源在短期内全部烧完"},{"key":"D","text":"新材料研制出来后不再考虑它的废弃处理"}],"a":"A","ex":"化学可以提供新材料和新流程，也要减少生产和使用中的污染。"},{"id":"cnk_j045_q4","tid":"cnk_j045","ty":"choice","df":"challenge","p":"化学对可持续发展的作用，较全面的说法是？","ch":[{"key":"A","text":"化学只会制造污染"},{"key":"B","text":"既能提供材料、能源和药物，也要控制污染并节约资源"},{"key":"C","text":"化学产品用完后环境一定自动恢复"},{"key":"D","text":"只要是新材料就没有缺点"}],"a":"B","ex":"化学改善了生活，同时需要绿色生产和合理使用，减少对环境的不利影响。"},{"id":"cnk_h001_q1","tid":"cnk_h001","ty":"choice","df":"basic","p":"化学主要研究的是哪一类问题？","ch":[{"key":"A","text":"只研究物体怎样运动得更快"},{"key":"B","text":"只研究生物怎样遗传"},{"key":"C","text":"物质的组成、结构、性质、转化及其应用"},{"key":"D","text":"只研究星球怎样运行"}],"a":"C","ex":"化学关心物质本身：由什么组成、结构怎样、有什么性质、如何转化、能做什么用。"},{"id":"cnk_h001_q2","tid":"cnk_h001","ty":"choice","df":"basic","p":"下列变化中，最需要用化学来研究的是？","ch":[{"key":"A","text":"书本从桌上拿到书包里"},{"key":"B","text":"冰融化成水但成分仍是水"},{"key":"C","text":"弹簧被拉长后又缩回去"},{"key":"D","text":"木炭燃烧后生成新的气体"}],"a":"D","ex":"燃烧生成了新物质，属于化学变化。搬动、状态改变和弹性形变没有生成新物质。"},{"id":"cnk_h001_q3","tid":"cnk_h001","ty":"choice","df":"standard","p":"用化学观点看物质，通常要进入哪一个层次？","ch":[{"key":"A","text":"原子、分子"},{"key":"B","text":"只看物体的外形和颜色"},{"key":"C","text":"只测量房间的长和宽"},{"key":"D","text":"只记录当天的气温"}],"a":"A","ex":"化学在原子、分子层次上解释组成、结构和变化，不只停留在外形或天气。"},{"id":"cnk_h001_q4","tid":"cnk_h001","ty":"choice","df":"challenge","p":"下列认识符合化学科学特点的是？","ch":[{"key":"A","text":"性质与组成无关，只能靠碰运气"},{"key":"B","text":"可以根据组成和结构解释性质，并利用性质实现转化"},{"key":"C","text":"化学变化不会生成新物质"},{"key":"D","text":"研究物质不必观察实验现象"}],"a":"B","ex":"组成和结构决定性质，性质决定用途和转化。结论要能跟现象、证据对上。"},{"id":"cnk_h002_q1","tid":"cnk_h002","ty":"choice","df":"basic","p":"下列物质属于纯净物的是？","ch":[{"key":"A","text":"空气"},{"key":"B","text":"矿泉水"},{"key":"C","text":"钢铁"},{"key":"D","text":"蒸馏水"}],"a":"D","ex":"蒸馏水只含水这一种物质。空气、矿泉水和钢铁都含有多种成分，是混合物。"},{"id":"cnk_h002_q2","tid":"cnk_h002","ty":"choice","df":"basic","p":"下列变化属于化学变化的是？","ch":[{"key":"A","text":"木炭在空气中燃烧"},{"key":"B","text":"水结成冰"},{"key":"C","text":"酒精挥发"},{"key":"D","text":"铁矿石被粉碎"}],"a":"A","ex":"燃烧生成了新物质。结冰、挥发和粉碎没有生成新物质。"},{"id":"cnk_h002_q3","tid":"cnk_h002","ty":"choice","df":"standard","p":"氧化物的共同特点是？","ch":[{"key":"A","text":"一定含有三种以上元素"},{"key":"B","text":"由两种元素组成，其中一种是氧元素"},{"key":"C","text":"一定是单质"},{"key":"D","text":"一定都能溶于水"}],"a":"B","ex":"氧化物是含氧的二元化合物，例如二氧化碳、氧化铜。单质只含一种元素。"},{"id":"cnk_h002_q4","tid":"cnk_h002","ty":"choice","df":"challenge","p":"把氧化铜变成铜单质，这种变化属于？","ch":[{"key":"A","text":"物理变化，只是颜色变浅"},{"key":"B","text":"只是把颗粒磨得更细"},{"key":"C","text":"化学变化，因为生成了新物质"},{"key":"D","text":"混合物的简单分层"}],"a":"C","ex":"氧化铜和铜是不同物质。有新物质生成，就是化学变化。"},{"id":"cnk_h003_q1","tid":"cnk_h003","ty":"choice","df":"basic","p":"下列物质属于电解质的是？","ch":[{"key":"A","text":"氯化钠"},{"key":"B","text":"蔗糖"},{"key":"C","text":"酒精"},{"key":"D","text":"石墨"}],"a":"A","ex":"氯化钠在水溶液或熔融时能电离出离子。蔗糖、酒精不能电离。石墨能导电，但它是单质，不是电解质。"},{"id":"cnk_h003_q2","tid":"cnk_h003","ty":"choice","df":"basic","p":"离子方程式主要表示的是？","ch":[{"key":"A","text":"某一个实验的全部操作顺序"},{"key":"B","text":"同一类型离子反应的实质"},{"key":"C","text":"只有颜色变化"},{"key":"D","text":"只有气体的体积"}],"a":"B","ex":"离子方程式把实际参加反应的离子写出来，用来表示一类反应的共同实质。"},{"id":"cnk_h003_q3","tid":"cnk_h003","ty":"choice","df":"standard","p":"稀盐酸与氢氧化钠溶液反应，离子方程式反映的实质是？","ch":[{"key":"A","text":"钠离子与氯离子结合成沉淀"},{"key":"B","text":"只有水分子互相碰撞"},{"key":"C","text":"氢离子与氢氧根离子结合成水"},{"key":"D","text":"氢离子与钠离子结合成氢气"}],"a":"C","ex":"中和的实质是 H+ 与 OH- 生成水。钠离子和氯离子留在溶液里，不写成沉淀。"},{"id":"cnk_h003_q4","tid":"cnk_h003","ty":"choice","df":"challenge","p":"下列离子方程式书写正确的是？","ch":[{"key":"A","text":"Fe + Cu2+ = Fe3+ + Cu"},{"key":"B","text":"H+ + OH- = H2↑"},{"key":"C","text":"Na+ + Cl- = NaCl↓"},{"key":"D","text":"Ba2+ + SO42- = BaSO4↓"}],"a":"D","ex":"钡离子与硫酸根生成硫酸钡沉淀，电荷也守恒。铁与铜离子反应生成的是 Fe2+，不是 Fe3+。氢离子与氢氧根生成水，不是氢气。氯化钠易溶，不能标成沉淀。"},{"id":"cnk_h004_q1","tid":"cnk_h004","ty":"choice","df":"basic","p":"氧化还原反应最明显的特征是？","ch":[{"key":"A","text":"一定有沉淀生成"},{"key":"B","text":"反应前后有元素的化合价发生变化"},{"key":"C","text":"一定有颜色变化"},{"key":"D","text":"各元素化合价都保持不变"}],"a":"B","ex":"有化合价变化才是氧化还原反应。沉淀或变色不是必需条件。"},{"id":"cnk_h004_q2","tid":"cnk_h004","ty":"choice","df":"basic","p":"在反应 2Na + Cl2 = 2NaCl 中，氯元素怎样变化？","ch":[{"key":"A","text":"化合价从 0 升到 +1，氯气作还原剂"},{"key":"B","text":"化合价始终是 -1"},{"key":"C","text":"化合价从 0 降到 -1，氯气作氧化剂"},{"key":"D","text":"化合价从 -1 升到 0"}],"a":"C","ex":"氯气中氯为 0 价，氯化钠中氯为 -1 价。化合价降低，氯气得电子，是氧化剂。"},{"id":"cnk_h004_q3","tid":"cnk_h004","ty":"choice","df":"standard","p":"氧化剂在反应中的变化是？","ch":[{"key":"A","text":"失电子，所含元素化合价升高"},{"key":"B","text":"质量和化学性质都不变"},{"key":"C","text":"只改变物质的聚集状态"},{"key":"D","text":"得电子，所含元素化合价降低"}],"a":"D","ex":"氧化剂使别的物质被氧化，自身得电子、化合价降低，被还原。"},{"id":"cnk_h004_q4","tid":"cnk_h004","ty":"choice","df":"challenge","p":"下列反应属于氧化还原反应的是？","ch":[{"key":"A","text":"Fe + CuSO4 = FeSO4 + Cu"},{"key":"B","text":"NaOH + HCl = NaCl + H2O"},{"key":"C","text":"CaCO3 高温分解成 CaO 和 CO2"},{"key":"D","text":"BaCl2 + Na2SO4 = BaSO4↓ + 2NaCl"}],"a":"A","ex":"铁把铜置换出来，铁和铜的化合价都变了。中和、碳酸钙分解和钡盐沉淀里各元素化合价不变。"},{"id":"cnk_h005_q1","tid":"cnk_h005","ty":"choice","df":"basic","p":"下列变化既是化学变化，又是氧化还原反应的是？","ch":[{"key":"A","text":"水蒸发"},{"key":"B","text":"氯化钠溶于水"},{"key":"C","text":"碳在氧气中燃烧生成二氧化碳"},{"key":"D","text":"盐酸与氢氧化钠中和"}],"a":"C","ex":"碳从 0 价变到 +4 价，氧从 0 价变到 -2 价。蒸发不是化学变化。溶解和中和没有化合价变化。"},{"id":"cnk_h005_q2","tid":"cnk_h005","ty":"choice","df":"basic","p":"酸碱中和与氧化还原反应的一个主要区别是？","ch":[{"key":"A","text":"中和反应一定没有离子参加"},{"key":"B","text":"氧化还原反应一定不生成新物质"},{"key":"C","text":"两类反应都一定生成沉淀"},{"key":"D","text":"中和反应里各元素化合价不变，氧化还原反应里有化合价变化"}],"a":"D","ex":"中和是 H+ 与 OH- 生成水，化合价不变。氧化还原必有化合价升降。"},{"id":"cnk_h005_q3","tid":"cnk_h005","ty":"choice","df":"standard","p":"稀硫酸使紫色石蕊变红，氢氧化钠溶液使酚酞变红。用离子来解释，正确的是？","ch":[{"key":"A","text":"酸溶液中的氢离子、碱溶液中的氢氧根离子分别导致这两种变色"},{"key":"B","text":"变色说明一定发生了氧化还原"},{"key":"C","text":"只有单质才能使指示剂变色"},{"key":"D","text":"石蕊和酚酞本身都是沉淀"}],"a":"A","ex":"酸的特征离子是 H+，碱的特征离子是 OH-。指示剂变色用来认识溶液中的这些离子，不是氧化还原的标志。"},{"id":"cnk_h005_q4","tid":"cnk_h005","ty":"choice","df":"challenge","p":"下列离子在水溶液中不能大量共存的是？","ch":[{"key":"A","text":"Na+ 与 Cl-"},{"key":"B","text":"H+ 与 OH-"},{"key":"C","text":"K+ 与 NO3-"},{"key":"D","text":"Na+ 与 SO42-"}],"a":"B","ex":"氢离子和氢氧根会结合成水，不能大量共存。其余几组不生成沉淀、气体或水。"},{"id":"cnk_h006_q1","tid":"cnk_h006","ty":"choice","df":"basic","p":"钠在空气中燃烧，生成的淡黄色固体主要是？","ch":[{"key":"A","text":"只有白色的氯化钠"},{"key":"B","text":"碳酸氢钠"},{"key":"C","text":"氢氧化铁"},{"key":"D","text":"过氧化钠"}],"a":"D","ex":"钠在空气中燃烧生成淡黄色的过氧化钠。碳酸氢钠和氢氧化铁不是这个反应的产物。"},{"id":"cnk_h006_q2","tid":"cnk_h006","ty":"choice","df":"basic","p":"一小块钠放入水中，可以看到的现象是？","ch":[{"key":"A","text":"钠浮在水面，熔成闪亮的小球，并产生气体"},{"key":"B","text":"钠沉到水底且没有任何气体"},{"key":"C","text":"溶液一定变成强酸性"},{"key":"D","text":"产生的气体能使澄清石灰水变浑浊"}],"a":"A","ex":"钠的密度比水小，反应放热使钠熔化，同时生成氢气和氢氧化钠。氢气不能使澄清石灰水变浑浊。"},{"id":"cnk_h006_q3","tid":"cnk_h006","ty":"choice","df":"standard","p":"碳酸钠和碳酸氢钠都能与酸反应。加热时更容易分解并放出二氧化碳的是？","ch":[{"key":"A","text":"碳酸钠"},{"key":"B","text":"碳酸氢钠"},{"key":"C","text":"氯化钠"},{"key":"D","text":"氢氧化钠"}],"a":"B","ex":"碳酸氢钠受热较易分解，生成碳酸钠、二氧化碳和水。碳酸钠、氯化钠、氢氧化钠受热不易这样分解。"},{"id":"cnk_h006_q4","tid":"cnk_h006","ty":"choice","df":"challenge","p":"鉴别碳酸钠溶液和氢氧化钠溶液，合理的方法是？","ch":[{"key":"A","text":"加入酚酞，只有氢氧化钠会变红"},{"key":"B","text":"闻气味，氢氧化钠有刺激性气味而碳酸钠没有"},{"key":"C","text":"加入稀盐酸，有气泡产生的是碳酸钠溶液"},{"key":"D","text":"看颜色，碳酸钠溶液是蓝色的"}],"a":"C","ex":"碳酸钠与酸反应放出二氧化碳。两种溶液都显碱性，都能使酚酞变红，不能靠酚酞分开。"},{"id":"cnk_h007_q1","tid":"cnk_h007","ty":"choice","df":"basic","p":"氯气通常是怎样的气体？","ch":[{"key":"A","text":"黄绿色、有刺激性气味"},{"key":"B","text":"无色无味"},{"key":"C","text":"蓝色液体"},{"key":"D","text":"红色固体"}],"a":"A","ex":"氯气是黄绿色气体，有刺激性气味，有毒，不能直接凑近闻。"},{"id":"cnk_h007_q2","tid":"cnk_h007","ty":"choice","df":"basic","p":"新制氯水能使有色布条褪色，起漂白作用的主要微粒是？","ch":[{"key":"A","text":"氯离子"},{"key":"B","text":"次氯酸"},{"key":"C","text":"水分子"},{"key":"D","text":"钠离子"}],"a":"B","ex":"氯气与水反应生成盐酸和次氯酸。次氯酸有强氧化性，能使有色物质褪色。"},{"id":"cnk_h007_q3","tid":"cnk_h007","ty":"choice","df":"standard","p":"久置的氯水漂白能力变弱，主要原因是？","ch":[{"key":"A","text":"氯离子越来越多，漂白更强"},{"key":"B","text":"水全部变成了氧气"},{"key":"C","text":"次氯酸见光容易分解"},{"key":"D","text":"氯化钠有很强的漂白性"}],"a":"C","ex":"次氯酸不稳定，见光分解后漂白成分减少。氯化钠和氯离子没有这种漂白作用。"},{"id":"cnk_h007_q4","tid":"cnk_h007","ty":"choice","df":"challenge","p":"氯气与氢氧化钠溶液反应后，漂白作用通常来自生成的？","ch":[{"key":"A","text":"氯化钠"},{"key":"B","text":"氢气"},{"key":"C","text":"碳酸钠"},{"key":"D","text":"次氯酸钠"}],"a":"D","ex":"氯气与氢氧化钠反应生成氯化钠和次氯酸钠。次氯酸钠水解或酸化后能产生次氯酸，因而有漂白性。"},{"id":"cnk_h008_q1","tid":"cnk_h008","ty":"choice","df":"basic","p":"物质的量的符号和常用单位，正确的是？","ch":[{"key":"A","text":"符号是 m，单位是克"},{"key":"B","text":"符号是 n，单位是摩尔"},{"key":"C","text":"符号是 c，单位是升"},{"key":"D","text":"符号是 V，单位是帕"}],"a":"B","ex":"物质的量用 n 表示，单位是摩尔，符号 mol。质量用 m，浓度用 c。"},{"id":"cnk_h008_q2","tid":"cnk_h008","ty":"choice","df":"basic","p":"1 mol 任何物质含有的微粒数大约是？","ch":[{"key":"A","text":"6.02 个"},{"key":"B","text":"22.4 个"},{"key":"C","text":"6.02×10^23 个"},{"key":"D","text":"100 个"}],"a":"C","ex":"1 mol 微粒的数目约为 6.02×10^23，这个数叫阿伏加德罗常数。22.4 L 是标准状况下气体的体积，不是个数。"},{"id":"cnk_h008_q3","tid":"cnk_h008","ty":"numeric","df":"standard","p":"36 g 水的物质的量是多少摩尔？相对原子质量取 H 为 1、O 为 16。","a":"2","ex":"水的相对分子质量是 18，摩尔质量是 18 g/mol。n＝36/18＝2 mol。"},{"id":"cnk_h008_q4","tid":"cnk_h008","ty":"numeric","df":"challenge","p":"40 g 氢氧化钠溶于水，配成 2 L 溶液。物质的量浓度是多少 mol/L？相对原子质量取 Na 为 23、O 为 16、H 为 1。","a":"1/2","ex":"NaOH 的相对分子质量是 40，40 g 即 1 mol。c＝n/V＝1 mol / 2 L＝0.5 mol/L。"},{"id":"cnk_h009_q1","tid":"cnk_h009","ty":"choice","df":"basic","p":"下列关于钠和氯的说法，正确的是？","ch":[{"key":"A","text":"钠沉在水底且不反应"},{"key":"B","text":"干燥的氯化钠固体有强漂白性"},{"key":"C","text":"钠与水反应生成氢氧化钠和氢气，氯水的漂白主要靠次氯酸"},{"key":"D","text":"氯气是无色无味气体"}],"a":"C","ex":"钠与水生成碱和氢气。漂白来自次氯酸或次氯酸盐，不是干燥的氯化钠。氯气呈黄绿色。"},{"id":"cnk_h009_q2","tid":"cnk_h009","ty":"choice","df":"basic","p":"下列物质中，加热较易放出二氧化碳的是？","ch":[{"key":"A","text":"碳酸钠"},{"key":"B","text":"氯化钠"},{"key":"C","text":"过氧化钠"},{"key":"D","text":"碳酸氢钠"}],"a":"D","ex":"碳酸氢钠受热分解放出二氧化碳。碳酸钠、氯化钠和过氧化钠不是这个现象的典型来源。"},{"id":"cnk_h009_q3","tid":"cnk_h009","ty":"choice","df":"standard","p":"用物质的量描述溶液组成时，正确的关系是？","ch":[{"key":"A","text":"物质的量浓度等于溶质的物质的量除以溶液的体积"},{"key":"B","text":"物质的量浓度等于溶质质量除以溶剂质量"},{"key":"C","text":"1 mol 物质的质量一定都是 1 g"},{"key":"D","text":"溶液越稀，溶质的物质的量一定越大"}],"a":"A","ex":"c＝n/V，体积要用溶液体积，单位对应 mol/L。摩尔质量因物质而异，不是都等于 1 g/mol。"},{"id":"cnk_h009_q4","tid":"cnk_h009","ty":"numeric","df":"challenge","p":"11 g 二氧化碳的物质的量是多少摩尔？相对原子质量取 C 为 12、O 为 16。","a":"1/4","ex":"二氧化碳的相对分子质量是 44。n＝11/44＝1/4 mol。"},{"id":"cnk_h010_q1","tid":"cnk_h010","ty":"choice","df":"basic","p":"实验活动「配制一定物质的量浓度的溶液」主要要完成的是？","ch":[{"key":"A","text":"测定溶液的 pH"},{"key":"B","text":"把粗盐里的泥沙除掉"},{"key":"C","text":"电解水得到氢气"},{"key":"D","text":"配出体积和物质的量浓度都符合要求的溶液"}],"a":"D","ex":"这个实验的目的就是配制指定物质的量浓度的溶液，不是测定酸碱性或提纯粗盐。"},{"id":"cnk_h010_q2","tid":"cnk_h010","ty":"choice","df":"basic","p":"用来准确确定所配溶液体积的仪器是？","ch":[{"key":"A","text":"容量瓶"},{"key":"B","text":"烧杯"},{"key":"C","text":"蒸发皿"},{"key":"D","text":"普通试管"}],"a":"A","ex":"容量瓶在一定温度下有准确容积，定容时液面与刻度线相切。烧杯和试管不能用来定容。"},{"id":"cnk_h010_q3","tid":"cnk_h010","ty":"choice","df":"standard","p":"用固体配制溶液时，比较合理的做法是？","ch":[{"key":"A","text":"把固体直接倒进容量瓶并在瓶里加热"},{"key":"B","text":"先在烧杯里溶解并冷却，再转移到容量瓶中定容"},{"key":"C","text":"用容量瓶在酒精灯上煮沸溶液"},{"key":"D","text":"定容时故意加过刻度线再吸出"}],"a":"B","ex":"溶解和冷却在烧杯中完成，容量瓶只用于准确定容，不能加热，也不能当作反应容器。"},{"id":"cnk_h010_q4","tid":"cnk_h010","ty":"choice","df":"challenge","p":"定容时若俯视容量瓶的刻度线，所配溶液的物质的量浓度会？","ch":[{"key":"A","text":"偏小"},{"key":"B","text":"一定不变"},{"key":"C","text":"偏大"},{"key":"D","text":"一定变成 0"}],"a":"C","ex":"俯视时液面实际上还没到刻度线，溶液体积偏小。溶质的物质的量没变，c＝n/V 就偏大。"},{"id":"cnk_h011_q1","tid":"cnk_h011","ty":"choice","df":"basic","p":"把铁钉放入硫酸铜溶液，能观察到的主要变化是？","ch":[{"key":"A","text":"铁钉表面出现红色固体，溶液由蓝变浅"},{"key":"B","text":"溶液变成强酸性且没有固体"},{"key":"C","text":"铁钉完全不变化"},{"key":"D","text":"生成大量二氧化碳"}],"a":"A","ex":"铁把铜离子还原成铜，自身变成浅绿色的亚铁离子，所以看到红色的铜，蓝色变浅。"},{"id":"cnk_h011_q2","tid":"cnk_h011","ty":"choice","df":"basic","p":"检验溶液中的 Fe3+，常用的现象是？","ch":[{"key":"A","text":"加入酚酞后变成蓝色"},{"key":"B","text":"加入硫氰化钾溶液后出现血红色"},{"key":"C","text":"加入澄清石灰水后一定无现象"},{"key":"D","text":"溶液发出刺激性气味即可判定"}],"a":"B","ex":"Fe3+ 与硫氰根结合成血红色物质，这是检验三价铁的常用方法。"},{"id":"cnk_h011_q3","tid":"cnk_h011","ty":"choice","df":"standard","p":"下列关于铁的化合物，正确的是？","ch":[{"key":"A","text":"铁的化合物里铁只能是 0 价"},{"key":"B","text":"三价铁不能被还原"},{"key":"C","text":"Fe2+ 和 Fe3+ 可以在一定条件下相互转化"},{"key":"D","text":"二价铁和三价铁的化学性质完全相同"}],"a":"C","ex":"铁有 +2 和 +3 两种常见价态。氧化可使 +2 变为 +3，还原可使 +3 变为 +2。"},{"id":"cnk_h011_q4","tid":"cnk_h011","ty":"choice","df":"challenge","p":"下列反应中，铁元素化合价升高的是？","ch":[{"key":"A","text":"用一氧化碳把氧化铁还原成铁"},{"key":"B","text":"三价铁被还原成二价铁"},{"key":"C","text":"铁单质没有参加任何反应"},{"key":"D","text":"铁与稀硫酸反应生成硫酸亚铁和氢气"}],"a":"D","ex":"铁单质是 0 价，硫酸亚铁中铁是 +2 价，化合价升高，铁被氧化。氧化铁被还原时铁的化合价降低。"},{"id":"cnk_h012_q1","tid":"cnk_h012","ty":"choice","df":"basic","p":"合金是？","ch":[{"key":"A","text":"一定是只含一种元素的纯净物"},{"key":"B","text":"一种金属与其他金属或非金属熔合而成的具有金属特性的物质"},{"key":"C","text":"一定是盐的水溶液"},{"key":"D","text":"一定不能导电"}],"a":"B","ex":"合金通常由金属跟其他金属或非金属熔合而成，仍具有金属特性。"},{"id":"cnk_h012_q2","tid":"cnk_h012","ty":"choice","df":"basic","p":"生铁和钢的共同点是？","ch":[{"key":"A","text":"都是不含碳的纯铁"},{"key":"B","text":"都是钠的化合物"},{"key":"C","text":"都是铁的合金，主要成分都含铁和碳"},{"key":"D","text":"都是气体"}],"a":"C","ex":"生铁和钢都是铁碳合金。含碳量不同，性能也不同，但都不是纯铁。"},{"id":"cnk_h012_q3","tid":"cnk_h012","ty":"choice","df":"standard","p":"人们常把合金而不是纯金属用作结构材料，一个常见原因是？","ch":[{"key":"A","text":"合金一定比纯金属更易生锈且无法防护"},{"key":"B","text":"合金一定没有金属光泽"},{"key":"C","text":"合金不能加工成形"},{"key":"D","text":"合金的硬度等性能可以比纯金属更适合使用"}],"a":"D","ex":"合金的硬度、强度、耐蚀性等可以按需要调节，所以刀具、钢筋等常用合金。"},{"id":"cnk_h012_q4","tid":"cnk_h012","ty":"choice","df":"challenge","p":"下列物品主要利用了金属材料的是？","ch":[{"key":"A","text":"钢制桥梁"},{"key":"B","text":"棉布衣服"},{"key":"C","text":"玻璃窗"},{"key":"D","text":"木制桌面"}],"a":"A","ex":"钢是铁的合金，属于金属材料。棉、玻璃和木材不是金属材料。"},{"id":"cnk_h013_q1","tid":"cnk_h013","ty":"choice","df":"basic","p":"下列说法正确的是？","ch":[{"key":"A","text":"铁不能与酸反应"},{"key":"B","text":"钢是不含铁的纯碳"},{"key":"C","text":"铁能从硫酸铜溶液中置换出铜，钢是铁的合金"},{"key":"D","text":"三价铁不能用硫氰化钾检验"}],"a":"C","ex":"铁比铜活泼，能置换铜。钢是铁碳合金。硫氰化钾用于检验 Fe3+。"},{"id":"cnk_h013_q2","tid":"cnk_h013","ty":"choice","df":"basic","p":"Fe3+ 与 Fe2+ 的一个明显差别是？","ch":[{"key":"A","text":"两者都使硫氰化钾立刻变蓝"},{"key":"B","text":"两者都是 0 价"},{"key":"C","text":"两者都不能再发生变化"},{"key":"D","text":"Fe3+ 遇硫氰化钾溶液呈血红色，Fe2+ 没有这个现象"}],"a":"D","ex":"血红色是 Fe3+ 的特征现象。Fe2+ 需要先被氧化成 Fe3+ 才会出现这个颜色。"},{"id":"cnk_h013_q3","tid":"cnk_h013","ty":"choice","df":"standard","p":"选择金属材料时，主要依据是？","ch":[{"key":"A","text":"材料的性能要适合用途，例如硬度、强度和是否容易加工"},{"key":"B","text":"只看材料的颜色是否鲜艳"},{"key":"C","text":"含碳量越高一定越好"},{"key":"D","text":"合金一定不能用于承重"}],"a":"A","ex":"用途决定需要的性能。合金可以通过改变成分来调整硬度、强度等，不是越纯或含碳越高越好。"},{"id":"cnk_h013_q4","tid":"cnk_h013","ty":"choice","df":"challenge","p":"下列变化中，铁元素被氧化的是？","ch":[{"key":"A","text":"氧化铁被还原成铁"},{"key":"B","text":"铁与盐酸反应生成氯化亚铁"},{"key":"C","text":"Fe3+ 变为 Fe2+"},{"key":"D","text":"钢锭被切割成小块但成分不变"}],"a":"B","ex":"铁从 0 价升到 +2 价，被氧化。氧化铁炼成铁、三价变二价都是还原。切割钢锭没有改变化学价态。"},{"id":"cnk_h014_q1","tid":"cnk_h014","ty":"choice","df":"basic","p":"实验活动「铁及其化合物的性质」主要要认识的是？","ch":[{"key":"A","text":"怎样配制一定物质的量浓度的溶液"},{"key":"B","text":"同主族元素金属性怎样递变"},{"key":"C","text":"怎样测定铁的密度到很多位小数"},{"key":"D","text":"铁单质和铁的化合物有哪些典型反应"}],"a":"D","ex":"这个实验围绕铁及其化合物的化学性质，不是配溶液，也不是周期律实验。"},{"id":"cnk_h014_q2","tid":"cnk_h014","ty":"choice","df":"basic","p":"要确认反应后溶液里有没有 Fe3+，可以？","ch":[{"key":"A","text":"取少量溶液，滴加硫氰化钾溶液，看有没有血红色"},{"key":"B","text":"把整瓶溶液倒进水槽再看颜色"},{"key":"C","text":"凭气味判断价态"},{"key":"D","text":"加入酚酞，变红就说明是三价铁"}],"a":"A","ex":"硫氰化钾与 Fe3+ 显血红色。检验时取少量即可，酚酞变红说明的是碱性，不是价态。"},{"id":"cnk_h014_q3","tid":"cnk_h014","ty":"choice","df":"standard","p":"铁钉放入硫酸铜溶液后出现红色固体，这个现象说明？","ch":[{"key":"A","text":"铁的活动性比铜弱"},{"key":"B","text":"铁能把铜从铜盐溶液里置换出来"},{"key":"C","text":"生成的红色固体是三氧化二铁"},{"key":"D","text":"反应没有发生氧化还原"}],"a":"B","ex":"红色固体是铜。铁比铜活泼，铁被氧化，铜离子被还原。"},{"id":"cnk_h014_q4","tid":"cnk_h014","ty":"choice","df":"challenge","p":"做这个实验时，比较合理的做法是？","ch":[{"key":"A","text":"为了现象明显，把整瓶铁盐一次倒掉"},{"key":"B","text":"未贴标签的溶液可以尝一口来判断"},{"key":"C","text":"药品少量取用，废液按实验室要求收集，不倒回原瓶"},{"key":"D","text":"剩余的铁粉随便倒进酒精灯里"}],"a":"C","ex":"实验只用少量药品。未知液体不能品尝。废液要集中处理，不能倒回原试剂瓶，也不能随意投入火里。"},{"id":"cnk_h015_q1","tid":"cnk_h015","ty":"choice","df":"basic","p":"决定元素种类的是原子中的？","ch":[{"key":"A","text":"质子数"},{"key":"B","text":"中子数"},{"key":"C","text":"核外电子层数以外的温度"},{"key":"D","text":"原子的体积"}],"a":"A","ex":"质子数（核电荷数）决定元素种类。中子数不同可以是同种元素的不同核素。"},{"id":"cnk_h015_q2","tid":"cnk_h015","ty":"choice","df":"basic","p":"在元素周期表中，正确的说法是？","ch":[{"key":"A","text":"横行称为族，纵列称为周期"},{"key":"B","text":"横行称为周期，纵列称为族"},{"key":"C","text":"表中只按元素名称的笔画排列"},{"key":"D","text":"原子序数与质子数无关"}],"a":"B","ex":"周期表按原子序数从小到大排列。同一横行是同一周期，同一纵列是同一族。"},{"id":"cnk_h015_q3","tid":"cnk_h015","ty":"choice","df":"standard","p":"一种中性原子的质子数是 11。它的原子序数和核外电子数分别是？","ch":[{"key":"A","text":"原子序数 12，核外电子数 10"},{"key":"B","text":"原子序数 11，核外电子数 23"},{"key":"C","text":"原子序数 11，核外电子数 11"},{"key":"D","text":"原子序数等于中子数，与质子数无关"}],"a":"C","ex":"原子序数等于质子数。中性原子里质子数等于核外电子数，所以都是 11。"},{"id":"cnk_h015_q4","tid":"cnk_h015","ty":"choice","df":"challenge","p":"元素在周期表中的位置主要由什么决定？","ch":[{"key":"A","text":"该元素发现的年代"},{"key":"B","text":"单质在室温下的颜色"},{"key":"C","text":"元素名称的字数"},{"key":"D","text":"原子的质子数和核外电子排布"}],"a":"D","ex":"质子数决定原子序数，电子层数和最外层电子数决定它在哪一周期、哪一族。"},{"id":"cnk_h016_q1","tid":"cnk_h016","ty":"choice","df":"basic","p":"元素周期律说的是？","ch":[{"key":"A","text":"元素性质只跟发现顺序有关"},{"key":"B","text":"元素性质随原子序数递增而呈周期性变化"},{"key":"C","text":"同周期元素的性质完全相同"},{"key":"D","text":"质子数越大，金属性一定越强"}],"a":"B","ex":"随着原子序数增加，核外电子排布周期性重复，元素性质也周期性变化，不是单调变强。"},{"id":"cnk_h016_q2","tid":"cnk_h016","ty":"choice","df":"basic","p":"碱金属原子的最外层电子数一般是？","ch":[{"key":"A","text":"7"},{"key":"B","text":"8"},{"key":"C","text":"1"},{"key":"D","text":"4"}],"a":"C","ex":"碱金属位于第ⅠA 族，最外层只有 1 个电子，反应中容易失去。卤素最外层一般是 7 个。"},{"id":"cnk_h016_q3","tid":"cnk_h016","ty":"choice","df":"standard","p":"主族元素从同周期的左边到右边（稀有气体除外），金属性通常？","ch":[{"key":"A","text":"逐渐增强"},{"key":"B","text":"完全不变"},{"key":"C","text":"先增强再一定变成气体"},{"key":"D","text":"逐渐减弱"}],"a":"D","ex":"同周期从左到右，核电荷数增加，原子半径减小，失电子能力减弱，金属性减弱。"},{"id":"cnk_h016_q4","tid":"cnk_h016","ty":"choice","df":"challenge","p":"比较钠和钾的金属性，正确的预期是？","ch":[{"key":"A","text":"钾的金属性比钠强"},{"key":"B","text":"钠的金属性比钾强"},{"key":"C","text":"两者最外层电子数不同所以不能比较"},{"key":"D","text":"金属性与原子结构无关"}],"a":"A","ex":"钠和钾同主族，钾在钠的下面，原子半径更大，更易失电子，金属性更强。"},{"id":"cnk_h017_q1","tid":"cnk_h017","ty":"choice","df":"basic","p":"离子键通常存在于？","ch":[{"key":"A","text":"氢气分子中两个氢原子之间"},{"key":"B","text":"金刚石里只由碳原子组成的结构中"},{"key":"C","text":"阴阳离子之间，例如氯化钠"},{"key":"D","text":"氧气分子中两个氧原子之间"}],"a":"C","ex":"活泼金属和活泼非金属往往形成离子键。氢气、氧气分子里是共价键。"},{"id":"cnk_h017_q2","tid":"cnk_h017","ty":"choice","df":"basic","p":"共价键的形成方式是？","ch":[{"key":"A","text":"阴阳离子完全得失电子后只靠重力吸引"},{"key":"B","text":"原子核互相融合"},{"key":"C","text":"中子在原子之间转移"},{"key":"D","text":"原子之间共用电子对"}],"a":"D","ex":"共价键由共用电子对把原子结合在一起。电子得失形成的是离子，不是共价键。"},{"id":"cnk_h017_q3","tid":"cnk_h017","ty":"choice","df":"standard","p":"下列物质中化学键类型判断正确的是？","ch":[{"key":"A","text":"氯化钠含离子键，氯化氢分子含共价键"},{"key":"B","text":"氯化钠和氯化氢都只含离子键"},{"key":"C","text":"氢气分子含离子键"},{"key":"D","text":"氯化钠分子中两个原子只靠共价键结合"}],"a":"A","ex":"NaCl 由钠离子和氯离子构成，是离子键。HCl 分子中氢和氯共用电子对，是共价键。"},{"id":"cnk_h017_q4","tid":"cnk_h017","ty":"choice","df":"challenge","p":"下列说法正确的是？","ch":[{"key":"A","text":"所有含氯元素的物质都只含离子键"},{"key":"B","text":"活泼金属与活泼非金属化合时，往往形成离子键"},{"key":"C","text":"共价化合物在任何条件下都不能导电"},{"key":"D","text":"离子化合物中一定没有阴阳离子"}],"a":"B","ex":"钠和氯形成氯化钠，是典型的离子键。氯化氢含氯却是共价分子。离子化合物由阴阳离子构成。"},{"id":"cnk_h018_q1","tid":"cnk_h018","ty":"choice","df":"basic","p":"原子序数增大时，元素性质的变化特点是？","ch":[{"key":"A","text":"金属性一直增强"},{"key":"B","text":"最外层电子数一直增加且不会重复"},{"key":"C","text":"质子数不再等于原子序数"},{"key":"D","text":"呈周期性变化，而不是一直朝同一个方向变"}],"a":"D","ex":"电子排布周期性变化，所以性质也周期性变化。最外层电子数会在新的周期重新开始。"},{"id":"cnk_h018_q2","tid":"cnk_h018","ty":"choice","df":"basic","p":"同主族从上到下，碱金属的金属性？","ch":[{"key":"A","text":"逐渐增强"},{"key":"B","text":"逐渐减弱"},{"key":"C","text":"完全相同"},{"key":"D","text":"与最外层电子数从 1 变到 8 有关"}],"a":"A","ex":"碱金属最外层都是 1 个电子。从上到下原子半径增大，更易失电子，金属性增强。"},{"id":"cnk_h018_q3","tid":"cnk_h018","ty":"choice","df":"standard","p":"下列配对正确的是？","ch":[{"key":"A","text":"氯化钠：只有共价键；氯化氢：只有离子键"},{"key":"B","text":"氯化钠：离子键；氢气：共价键"},{"key":"C","text":"氧气分子：离子键"},{"key":"D","text":"同周期元素的化学键类型一定完全相同"}],"a":"B","ex":"氯化钠是离子化合物。氢气、氧气分子中是共价键。化学键类型要看具体微粒，不能只按周期一概而论。"},{"id":"cnk_h018_q4","tid":"cnk_h018","ty":"choice","df":"challenge","p":"钠、镁、铝位于同一周期，从钠到铝，金属性的变化和结构原因是？","ch":[{"key":"A","text":"金属性增强，因为最外层电子数减少"},{"key":"B","text":"金属性不变，因为它们质子数相同"},{"key":"C","text":"金属性减弱，因为核电荷数增加、原子半径减小，更难失电子"},{"key":"D","text":"金属性增强，因为它们变成了同主族"}],"a":"C","ex":"钠、镁、铝同周期相邻。从左到右核电荷数增加，原子半径减小，失电子变难，金属性减弱。"},{"id":"cnk_h019_q1","tid":"cnk_h019","ty":"choice","df":"basic","p":"实验活动「同周期、同主族元素性质的递变」要观察的是？","ch":[{"key":"A","text":"同一周期或同一主族里，元素性质怎样依次变化"},{"key":"B","text":"怎样配制一定物质的量浓度的溶液"},{"key":"C","text":"怎样测定阿伏加德罗常数的精确值"},{"key":"D","text":"怎样把石油分成各种馏分"}],"a":"A","ex":"这个实验用来验证周期律：同周期、同主族元素的性质有递变，不是配溶液或炼油。"},{"id":"cnk_h019_q2","tid":"cnk_h019","ty":"choice","df":"basic","p":"比较钠、镁、铝的金属性时，可以看它们与水或酸反应的？","ch":[{"key":"A","text":"生成物是否一定都是黄色固体"},{"key":"B","text":"剧烈程度"},{"key":"C","text":"原子质量是否完全相等"},{"key":"D","text":"是否都使酚酞变成蓝色且没有任何差别"}],"a":"B","ex":"金属性越强，与水或酸反应通常越剧烈。钠、镁、铝的反应剧烈程度依次减弱，对应金属性减弱。"},{"id":"cnk_h019_q3","tid":"cnk_h019","ty":"choice","df":"standard","p":"同主族从上到下比较碱金属，实验预期的趋势是？","ch":[{"key":"A","text":"金属性逐渐减弱"},{"key":"B","text":"核电荷数逐渐减小"},{"key":"C","text":"金属性逐渐增强"},{"key":"D","text":"最外层电子数从 1 增加到 8"}],"a":"C","ex":"碱金属同主族从上到下，原子半径增大，失电子更容易，金属性增强。最外层电子数仍是 1。"},{"id":"cnk_h019_q4","tid":"cnk_h019","ty":"choice","df":"challenge","p":"做钠与水的对比时，比较合理的安全做法是？","ch":[{"key":"A","text":"把一大块钠投入沸水并凑近观看"},{"key":"B","text":"用手直接抓钠并在水里搓洗"},{"key":"C","text":"剩余的钠带着水放回原瓶"},{"key":"D","text":"只用一小块钠，用镊子取用，不要用手直接接触"}],"a":"D","ex":"钠与水反应剧烈。只用一小块，用镊子夹取。不能用手接触，也不能把沾水的钠放回原瓶。"}];
